  FT["PH-H2057"] = {"id":"PH-H2057","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2324_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予伊洛伊洛省Barotac Viejo市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting the Municipality of Barotac Viejo, Province of Iloilo, a Franchise for an Electric Light, Heat and Power System","orig":"An Act Granting the Municipality of Barotac Viejo, Province of Iloilo, a Franchise for an Electric Light, Heat and Power System"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2324","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2324_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2057-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established Act Numbered Thirty-six hundred thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, and to the provisions of the Constitution, there is granted to the Municipality of Barotac Viejo, Province of Iloilo, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the limits of the said municipality."}},{"id":"PH-H2057-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2057-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2057-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Municipality of Barotac Viejo, Province of Iloilo, a Franchise for an Electric Light, Heat and Power System","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2058"] = {"id":"PH-H2058","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2325_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第309号共和国法第4条，规定赛马可在每周六全天举行，而非如该法现行规定仅在周六下午举行的法案","en":"An Act to Amend Section Four of Republic Act Numbered Three Hundred and Nine by Providing that Horse Races May be Held All Day on Saturdays, Instead of on Saturday Afternoons Only as is Now Provided by Said Act","orig":"An Act to Amend Section Four of Republic Act Numbered Three Hundred and Nine by Providing that Horse Races May be Held All Day on Saturdays, Instead of on Saturday Afternoons Only as is Now Provided by Said Act"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2325","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2325_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2058-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section four of Republic Act Numbered Three hundred and nine is hereby amended to read as follows:\nSec. 4 . Racing days. -Private individuals and entities duly licensed by the Games and Amusements Board may hold horse races on Sundays not reserved under this Act, on twenty-four Saturdays as may be determined by the said Board, and on legal holidays except Thursday and Friday of Holy Week, July fourth, commonly known as Independence Day, and December thirtieth, commonly known as Rizal Day. The second Sunday and the first Saturday of each month shall be reserved for races held by the Philippine Tuberculosis Society. The fourth Sunday of February, April, June, August, October and the third Sunday of December shall be reserved for races held by the Philippine Charity Sweepstakes Office. The fourth Sunday of January, May, July, and September and the second Saturday of January, April, July and October shall be reserved for races held by the White Cross, Inc. The fourth Sunday of March shall also be reserved for the national race, commonly known as the Grand Derby Race, held by the Philippine Tuberculosis Society. Other Saturdays shall be reserved for races authorized by the President of the Philippines for charitable, relief or civic purposes.\""}},{"id":"PH-H2058-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Four of Republic Act Numbered Three Hundred and Nine by Providing that Horse Races May be Held All Day on Saturdays, Instead of on Saturday Afternoons Only as is Now Provided by Said Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2059"] = {"id":"PH-H2059","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2326_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予萨马省Borongan市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting the Municipality of Borongan, Province of Samar, a Franchise for an Electric Light, Heat and Power System","orig":"An Act Granting the Municipality of Borongan, Province of Samar, a Franchise for an Electric Light, Heat and Power System"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2326","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2326_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2059-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, and to the provisions of the Constitution, there is granted to the Municipality of Borongan, Province of Samar, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the limits of the said municipality."}},{"id":"PH-H2059-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2059-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2059-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Municipality of Borongan, Province of Samar, a Franchise for an Electric Light, Heat and Power System","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2060"] = {"id":"PH-H2060","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2327_1959.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将政府公司法律顾问职位与总检察长职位区分、规定其任命与薪金并拨付必要经费，并为其他目的","en":"An Act to Declare the Position of Government Corporate Counsel Distinct and Separate from that of the Solicitor General, Provide for His Appointment and Salary and Appropriate the Necessary Funds Therefor, and for Other Purposes","orig":"An Act to Declare the Position of Government Corporate Counsel Distinct and Separate from that of the Solicitor General, Provide for His Appointment and Salary and Appropriate the Necessary Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 2327","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2327_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2060-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The position of Government Corporate Counsel is hereby declared distinct and separate from that of the Solicitor General. The Government Corporate Counsel, who shall be appointed by the President of the Philippines with the consent of the Commission on Appointments, shall head the Office of the Government Corporate Counsel as presently constituted. He shall have the rank and privileges of an Undersecretary of Department and shall receive compensation of twelve thousand pesos per annum. He shall have full control and supervision over all legal divisions maintained separately by Government owned or controlled corporations with respect to handling of legal matters."}},{"id":"PH-H2060-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The positions of two assistant government corporate counselors are hereby created with a salary of nine thousand and eight thousand four hundred pesos per annum, respectively who shall be appointed by the Secretary of Justice upon recommendation of the Government Corporate Counsel."}},{"id":"PH-H2060-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby appropriated, out of the savings of prior years’ appropriations assessed upon Government-owned or controlled corporations, the sum of forty thousand pesos or so much thereof as may be necessary, to pay for the salary and other expenses incidental to the separation of the position of Government Corporate Counsel and the creation of two assistant government corporate counselors."}},{"id":"PH-H2060-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All Acts or parts thereof as may be inconsistent with the provisions hereof are hereby repealed or modified accordingly."}},{"id":"PH-H2060-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Declare the Position of Government Corporate Counsel Distinct and Separate from that of the Solicitor General, Provide for His Appointment and Salary and Appropriate the Necessary Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2061"] = {"id":"PH-H2061","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2328_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Marcelo Secuya在达沃省Nabunturan市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting Marcelo Secuya a Franchise for an Electric Light, Heat and Power System in the Municipality of Nabunturan, Province of Davao","orig":"An Act Granting Marcelo Secuya a Franchise for an Electric Light, Heat and Power System in the Municipality of Nabunturan, Province of Davao"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2328","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2328_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2061-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Marcelo Secuya, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Nabunturan, Province of Davao."}},{"id":"PH-H2061-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2061-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2061-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Marcelo Secuya a Franchise for an Electric Light, Heat and Power System in the Municipality of Nabunturan, Province of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2062"] = {"id":"PH-H2062","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2329_1959.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Democrito O. Plaza 在菲律宾境内建设、设立、维护和运营私人固定点对点无线电台的临时许可的法案","en":"An Act Granting Democrito O. Plaza a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Democrito O. Plaza a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2329","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2329_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2062-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Democrito O. Plaza a temporary permit to construct, establish, maintain and operate in the Philippines, at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point radio stations, for the reception and transmission of wireless messages on radiotelegraphy or radio-telephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H2062-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point radio stations or any of them in lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H2062-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee upon the express condition that the same shall be void unless the construction of at least one of the said stations be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H2062-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate private fixed point-to-point radio stations at such places in the Philippines as the interest of the grantee and of his business may justify."}},{"id":"PH-H2062-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder, but the grantee may use the international distress frequency of five hundred kilocycles and the high distress frequency of eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H2062-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees are chargeable, as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H2062-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall so construct and operate his radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H2062-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the National, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of his radio stations."}},{"id":"PH-H2062-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder, to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, firm, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H2062-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H2062-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Wherever in this permit the term \"grantee\" is used, it shall be held and understood to mean \"Democrito O. Plaza,\" his representatives, successors, or assigns, unless the context indicates otherwise."}},{"id":"PH-H2062-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This temporary permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H2062-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Democrito O. Plaza a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2063"] = {"id":"PH-H2063","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2330_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Romeo Firme在伊莎贝拉省Aurora市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting Romeo Firme a Franchise for an Electric Light, Heat and Power System in the Municipality of Aurora, Province of Isabela","orig":"An Act Granting Romeo Firme a Franchise for an Electric Light, Heat and Power System in the Municipality of Aurora, Province of Isabela"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2330","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2330_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2063-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Romeo Firme, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Aurora, Province of Isabela."}},{"id":"PH-H2063-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to the rates."}},{"id":"PH-H2063-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and turn over to the government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2063-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Romeo Firme a Franchise for an Electric Light, Heat and Power System in the Municipality of Aurora, Province of Isabela","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2064"] = {"id":"PH-H2064","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2331_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将第340号共和国法（经修正）的福利扩及此前依该法退休、退休生效日期在第1862号共和国法生效日或之前的某些军人，为此修订第1862号共和国法第1条的法案","en":"An Act to Extend the Benefits of Republic Act Numbered Three Hundred Forty, as Amended, to Certain Military Personnel Heretofore Retired Under Said Act with Effective Date of Retirement on or Prior to the Effective Date of Republic Act Numbered Eighteen Hundred Sixty-Two, by Amending for the Purpose Section One of Republic Act Numbered Eighteen Hundred Sixty-Two","orig":"An Act to Extend the Benefits of Republic Act Numbered Three Hundred Forty, as Amended, to Certain Military Personnel Heretofore Retired Under Said Act with Effective Date of Retirement on or Prior to the Effective Date of Republic Act Numbered Eighteen Hundred Sixty-Two, by Amending for the Purpose Section One of Republic Act Numbered Eighteen Hundred Sixty-Two"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 2331","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2331_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2064-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Eighteen hundred and sixty-two is hereby amended to read as follows:\n\"Sec. 1. The provisions of existing law to the contrary notwithstanding, and subject to the special provisions and limitations hereinafter provided, the provisions of Republic Act Numbered Three hundred forty, including all amendments thereto on the date this Act takes effect, shall be and are hereby made applicable to persons (1) retired under the provisions of Commonwealth Act Numbered One hundred ninety, or (2) honorably separated with gratuity under subsection (g), section twenty-two of Commonwealth Act Numbered One, otherwise known as the National Defense Act, or (3) retired under Republic Act Numbered Three hundred forty with effective date of retirement on or prior to the effective date of this Act, or (4) retired under Act Numbered Forty-one hundred fifty-one, and which persons \"(a) were in the active service of the Philippine Army or any guerrilla organization duly recognized as a component thereof, at any time between December eight, nineteen hundred forty-one and September two, nineteen hundred forty-five; and \"(b) had completed at least twenty years' active service on the date of their original retirement or separation: Provided , That persons separated with gratuity on account of physical disability under subsection (g), section twenty-two of Commonwealth Act Numbered One who had less than twenty years' active service on the date of their original separation, shall be entitled to the benefits of the proviso contained in section eight of Republic Act Numbered Three hundred forty.\""}},{"id":"PH-H2064-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Extend the Benefits of Republic Act Numbered Three Hundred Forty, as Amended, to Certain Military Personnel Heretofore Retired Under Said Act with Effective Date of Retirement on or Prior to the Effective Date of Republic Act Numbered Eighteen Hundred Sixty-Two, by Amending for the Purpose Section One of Republic Act Numbered Eighteen Hundred Sixty-Two","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2065"] = {"id":"PH-H2065","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2332_1959.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"修订第 2393 号法（授予 Silay 电力与制冰公司在西内格罗斯 Silay 市镇经营电灯、热力与动力系统的特许权）","en":"An Act to Amend Act Numbered Twenty-Three Hundred and Ninety-Three, Entitled “An Act Granting to the Sociedad Anonima Known as ‘Silay Electric and Ice Plant Company, Incorporated,’ a Franchise to Install, Operate, and Maintain an Electric Light, Heat and Power System in the Municipality of Silay, Occidental Negros, Philippine Islands”","orig":"An Act to Amend Act Numbered Twenty-Three Hundred and Ninety-Three, Entitled “An Act Granting to the Sociedad Anonima Known as ‘Silay Electric and Ice Plant Company, Incorporated,’ a Franchise to Install, Operate, and Maintain an Electric Light, Heat and Power System in the Municipality of Silay, Occidental Negros, Philippine Islands”"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 2332","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2332_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2065-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section three of Act Numbered Twenty-three hundred and ninety-three is amended to read as follows:\n\"Sec. 3. The poles erected by the grantee shall be of such height as to maintain the wires stretched on the same at a distance of at least twenty feet above the level of the ground, and shall be of such appearance as not to disfigure the streets, and shall be place in accordance with a plan approved by the municipal authorities, and said grantee shall supply electric power, heat and light to any applicant for the same within fifteen days after the date of application, and as between such applicant and other applicants, in the order of the date of his application up to the limit of the capacity of the plant of said grantee, to be determined by the district engineer on the application of said association or said grantee, and should the demand for electric power, heat and light at any time increase beyond the capacity of the plant of said grantee to supply the same the capacity of said plant shall be increased to meet such demand, upon authorization by the municipal council of Silay. The point at which the electric power, heat or light is to be supplied shall not be more than thirty meters from the lines or wires operated by said grantee.\""}},{"id":"PH-H2065-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section eleven of the same Act is amended to read as follows:\n\"Sec. 11. This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines and that all lands or rights of use or occupation of lands secured by virtue of this franchise shall revert upon its termination to the Insular, provincial or municipal governments who were the owners thereof upon the date of which this franchise was granted.\""}},{"id":"PH-H2065-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"A new section is inserted between sections eleven and twelve of the same Act to read as follows:\n\"Sec. 11-A. It is expressly provided that in the event the government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the government all serviceable equipment therein, at cost, less reasonable depreciation.\""}},{"id":"PH-H2065-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section seventeen of the same Act is repealed."}},{"id":"PH-H2065-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The present franchise of the Silay Electric and Ice Plant Co., Inc., is hereby extended for an additional fifty years from and after February twenty-eight, nineteen hundred and sixty-four."}},{"id":"PH-H2065-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Act Numbered Twenty-Three Hundred and Ninety-Three, Entitled “An Act Granting to the Sociedad Anonima Known as ‘Silay Electric and Ice Plant Company, Incorporated,’ a Franchise to Install, Operate, and Maintain an Electric Light, Heat and Power System in the Municipality of Silay, Occidental Negros, Philippine Islands”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2066"] = {"id":"PH-H2066","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2333_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Dumlao Enterprises, Inc.在北伊罗戈省Batac市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting Dumlao Enterprises, Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of Batac, Province of Ilocos Norte","orig":"An Act Granting Dumlao Enterprises, Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of Batac, Province of Ilocos Norte"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2333","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2333_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2066-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, and to the provisions of the Constitution, there is granted to Dumlao Enterprises, Inc., for a period of fifty years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system, and/or obtain a power allocation from the National Power Corporation, for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Batac, Province of Ilocos Norte."}},{"id":"PH-H2066-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2066-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2066-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Dumlao Enterprises, Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of Batac, Province of Ilocos Norte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2067"] = {"id":"PH-H2067","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2334_1959.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"规定菲律宾武装部队预备役军官在现役部队中轮换任职的法案","en":"An Act Providing for the Rotation of Reserve Officers of the Armed Forces of the Philippines in the Active Military Service","orig":"An Act Providing for the Rotation of Reserve Officers of the Armed Forces of the Philippines in the Active Military Service"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 2334","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2334_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2067-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Reserve officers of the Armed Forces of the Philippines shall be rotated in the active military service, subject to the limitations herein provided and under such rules and regulations as the Secretary of National Defense shall prescribe, for the primary purpose of making available or service in the event of emergency the maximum number of trained and qualified reserve officers."}},{"id":"PH-H2067-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"After the approval of this Act, and except in time of emergency, no reserve officer shall be called to extended tours of active duty exceeding a total of two years within any period of five consecutive years: Provided , That reserve officers on active duty for more than two years in the date of approval of this Act, with the exception of those covered by section three of this Act, shall be reverted to inactive status within three years from the approval of this Act: Provided , further , That hereafter calls to extended tours of active duty of reserve officers shall be in proportion to the officers requirements of each major service in the reserve force build-up program of the Armed Forces of the Philippines and the priority for selecting such reserve officers within each major service shall follow the order of age grouping for the reserve force as defined in section fifty-two of the National Defense Act, as amended."}},{"id":"PH-H2067-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The provisions of section two of this Act shall nor apply to reserve officers covered by the provisions of Republic Act Numbered Thirteen hundred eighty-two nor to those possessing technical qualifications, skills, and competence which are indispensable to the needs of the Armed Forces of the Philippines and for whom there are no satisfactory of the Philippines and for whom there are no satisfactory replacements from among reserve officers in the inactive status: Provided , That the selection of such officers shall be as determined by a Board of Officers to be appointed by the Chief of Staff."}},{"id":"PH-H2067-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Any reserve officer who is reverted to inactive duty under the provisions of this Act after having completed an accumulated period of active commissioned service of between five years and twenty years shall, unless he is already entitled to the retirement benefits under Republic Act Numbered Three hundred forty, as amended, be entitled upon reversion to receive a gratuity equivalent to one month's authorized base and longevity pay in the permanent rank held at the time of such reversion multiplied by his years of active commissioned service: Provided , That such reversion is not as a result of court martial action nor due to the officer's gross misconduct, the intemperate use of drugs or alcoholics, or inefficiency: Provided , however , That if a reserve officer is reemployed in a civilian office of the government or government-owned or controlled corporation, he shall not be made to reimburse the amounts received by him as gratuity under this Act: Provided , further , That if a reserve officer who has received gratuity under this Act reenters the active service, he shall not be eligible for a new gratuity until he has completed at least five years of active commissioned service from the date of such reentry, and no subsequent gratuity shall be paid covering any period of active commissioned service for which he has already received gratuity under this Act: Provided , further , That in case a reserve officer who has received gratuity under this Act subsequently reenters the active service and is retired pursuant to Republic act Numbered Three hundred forty, such gratuity shall be deducted from his retirement gratuity or pensions: And provided, finally, That for purposes of this section, any period of service amounting to six months or more shall be counted as one year."}},{"id":"PH-H2067-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Reserve officers who on the approval of this Act are on active duty and are reverted to inactive status by virtue of its provisions, shall be given priority in civilian employment in the government service or in that of government-owned or controlled corporations in parity with veterans, in positions and at salaries commensurate with their educational background, training and experience, provisions of the civil service regulations to the contrary notwithstanding."}},{"id":"PH-H2067-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Secretary of National Defense is authorized to use any savings in the appropriations of the Armed Forces of the Philippines to carry out the provisions of this Act during the first year of its implementation. Thereafter, the necessary funds shall be included in the annual appropriation for the Armed Forces of the Philippines."}},{"id":"PH-H2067-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Rotation of Reserve Officers of the Armed Forces of the Philippines in the Active Military Service","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2068"] = {"id":"PH-H2068","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2335_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Baliuag Electric Light and Power Company（巴利瓦格电灯与电力公司）在布拉干省巴利瓦格市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting to the Baliuag Electric Light and Power Company a Franchise for an Electric Light, Heat and Power System in the Municipality of Baliuag, Province of Bulacan","orig":"An Act Granting to the Baliuag Electric Light and Power Company a Franchise for an Electric Light, Heat and Power System in the Municipality of Baliuag, Province of Bulacan"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2335","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2335_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2068-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Baliuag Electric Lights and Power Company for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Baliuag, Province of Bulacan."}},{"id":"PH-H2068-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2068-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2068-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to the Baliuag Electric Light and Power Company a Franchise for an Electric Light, Heat and Power System in the Municipality of Baliuag, Province of Bulacan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2069"] = {"id":"PH-H2069","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2336_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Tanay市","en":"An Act Establishing a Summer Resort in Sampaloc, Municipality of Tanay, Province of Rizal","orig":"An Act Establishing a Summer Resort in Sampaloc, Municipality of Tanay, Province of Rizal"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2336","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2336_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2069-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a summer resort in Sampaloc, Municipality of Tanay, Province of Rizal. The Commission on Parks and Wildlife shall issue such rules and regulations for the establishment of such resort."}},{"id":"PH-H2069-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29"};
  FT["PH-H2070"] = {"id":"PH-H2070","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2337_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Jose Araneta在北三宝颜省Siocon市镇电灯、热力与动力系统特许经营权的法案","en":"An Act to Grant Jose Araneta a Franchise for an Electric Light, Heat and Power System in the Municipality of Siocon, Province of Zamboanga del Norte","orig":"An Act to Grant Jose Araneta a Franchise for an Electric Light, Heat and Power System in the Municipality of Siocon, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2337","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2337_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2070-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Jose Araneta, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Siocon, Province of Zamboanga del Norte."}},{"id":"PH-H2070-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric hear and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2070-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2070-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Grant Jose Araneta a Franchise for an Electric Light, Heat and Power System in the Municipality of Siocon, Province of Zamboanga del Norte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2071"] = {"id":"PH-H2071","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2338_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"规定对检举违反国内税收与海关法律者给予奖励的法案","en":"An Act to Provide for Reward to Informers of Violations of the Internal Revenue and Customs Laws","orig":"An Act to Provide for Reward to Informers of Violations of the Internal Revenue and Customs Laws"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2338","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2338_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2071-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any person, except an internal revenue or customs official or employee, or other public officials, or his relative within the sixth degree of consanguinity, who voluntarily gives definite and sworn information, stating the facts constituting as grounds for such information not yet in the possession of the Bureau of Internal Revenue or the Bureau of Customs, leading to the discovery of frauds upon the internal revenue or customs laws, or violations of any of the provisions thereof, thereby resulting in the recovery of revenues, surcharges and fees and/or the conviction of the guilty party and/or the imposition of any fine or penalty shall be rewarded in a sum equivalent to twenty-five per centum of the revenues, surcharges or fees recovered and/or fine or penalty imposed and collected. The same amount of reward shall also be given to informer or informers where the violator has offered to compromise the violation of law committed by him and his offer has been accepted by the Commissioner of Internal Revenue or the Commissioner of Customs, as the case may be, and in such a case the twenty-five per centum reward fixed herein shall be based on the amount agreed in the compromise and collected from the violator: Provided , That should no revenue surcharges or fees be actually recovered or collected, such persons should not be entitled to a reward: Provided , further , That the information required herein shall not refer to a case already pending or previously investigated or examined by the Commissioner of Internal Revenue or the Commissioner of Customs, or any of their deputies, agents or examiners, as the case may be, or the Secretary of Finance or any of his deputies or agents: Provided , finally , That the reward provided herein shall be paid under regulations issued jointly by the Commissioners of Internal Revenue and Customs with the approval of the Secretary of Finance, and that the determination of the degree of relationship between the Internal Revenue or Customs official or employee and the informer shall be left not only to the Commissioner of Internal Revenue or the Commissioner of Customs, as the case may be, but should be jointly made by such official and the Solicitor General.\nThe reward herein authorized shall be paid out of revenues, surcharges, compromises, and penalties established by law, collected and accounted for as a result of the information furnished by the informer."}},{"id":"PH-H2071-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Should the information later turn out or be proved to be false or to have been made only for the purpose of harassing, molesting or in any way prejudicing the person so denounced, the person so denounced shall be entitled to any action, criminal or civil, as the facts may warrant: Provided , That the identify of the informer shall not be revealed except when the information is proven to be malicious or false."}},{"id":"PH-H2071-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section thirty-five hundred and thirteen of Republic Act Numbered Nineteen hundred and thirty-seven, otherwise known as the Tariff and Customs Code, is hereby repealed."}},{"id":"PH-H2071-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for Reward to Informers of Violations of the Internal Revenue and Customs Laws","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2072"] = {"id":"PH-H2072","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2339_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将Tacloban Electric Light and Ice Plants在塔克洛班市经营电灯、热力与动力系统的特许经营权期限予以延长并作出相关规定的法案","en":"An Act Extending the Term of the Electric Light, Heat and Power Franchise of the Tacloban Electric Light and Ice Plants Co., Inc.","orig":"An Act Extending the Term of the Electric Light, Heat and Power Franchise of the Tacloban Electric Light and Ice Plants Co., Inc."},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2339","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2339_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2072-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, and the provisions of the Constitution, the term of the electric light, heat and power system franchise granted to J. V. House by Act Numbered Twenty-seven hundred, as amended, and later transferred to the Tacloban Electric Light and Ice Plants Co., Inc., in accordance with the provisions of the last mentioned Act, is extended for a period of twenty-five years from the date of expiration of the said franchise."}},{"id":"PH-H2072-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"It is expressly provided that in the event the government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2072-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Term of the Electric Light, Heat and Power Franchise of the Tacloban Electric Light and Ice Plants Co., Inc.","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2073"] = {"id":"PH-H2073","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2340_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"批准将Escudero电力服务公司的特许经营权及全部财产与权利转让给Manila电力公司的法案","en":"An Act Approving the Transfer of the Franchise and All Property and Rights of Escudero Electric Service Company to Manila Electric Company, and for Other Purposes","orig":"An Act Approving the Transfer of the Franchise and All Property and Rights of Escudero Electric Service Company to Manila Electric Company, and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2340","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2340_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2073-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The transfer and assignment to Manila Electric company of the franchise and all property and rights by the Escudero Electric Service Company under the franchise granted it by Act Numbered Thirty-six hundred forty-eight of the Philippine Legislature, together with the right to install, operate and maintain an electric light, heat and power system in the City of San Pablo, and in the municipalities of Alaminos, Province of Laguna, and Dolores and Tiaong, Province of Quezon, Philippines, is hereby approved: Provided, That the schedule of rates in the City of Manila of the Manila Electric Company shall be applied at all times in the area covered by legislative or Public Service Commission franchises of the Escudero Electric Service Company; that the pre-war lines of the Escudero Electric Service Company which were destroyed, shall be rehabilitated and reconstructed by the Manila Electric Company within one year from the date of the approval of this Act; and that the lines to other barrios within the area of said franchises shall likewise be extended as public service demands and warrants as soon as possible."}},{"id":"PH-H2073-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"From and after the approval of this Act, whenever and wherever in Act Numbered Thirty-six hundred forty-eight of the Philippine Legislature the name Escudero Electric Service Company is mentioned, it shall be changed to and shall henceforth be understood to mean the Manila Electric Company."}},{"id":"PH-H2073-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Approving the Transfer of the Franchise and All Property and Rights of Escudero Electric Service Company to Manila Electric Company, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2074"] = {"id":"PH-H2074","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2341_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Angeles Electric Corporation在安赫莱斯市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting the Angeles Electric Corporation a Franchise for an Electric Light, Heat and Power System in the Municipality of Angeles, Province of Pampanga","orig":"An Act Granting the Angeles Electric Corporation a Franchise for an Electric Light, Heat and Power System in the Municipality of Angeles, Province of Pampanga"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2341","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2341_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2074-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Angeles Electric Corporation, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Angeles, Province of Pampanga."}},{"id":"PH-H2074-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2074-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2074-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval: Provided, That should the grantee fail to construct and operate its electric light, heat and power system within three years from the approval of this Act, the franchise therefor shall be null and void.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Angeles Electric Corporation a Franchise for an Electric Light, Heat and Power System in the Municipality of Angeles, Province of Pampanga","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2075"] = {"id":"PH-H2075","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2342_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"进一步修订第1162号共和国法（经修正）若干条款并为其他目的法案","en":"An Act to Further Amend Certain Sections of Republic Act Numbered Eleven Hundred and Sixty-Two, as Amended, and for Other Purposes","orig":"An Act to Further Amend Certain Sections of Republic Act Numbered Eleven Hundred and Sixty-Two, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2342","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2342_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2075-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one and two of Republic Act Numbered Eleven hundred and sixty-two, as amended, is further amended to read as follows:\n\"Sec. 1. The expropriation of landed estates or haciendas, or lands which formerly formed part thereof, or any piece of land in the City of Manila, Quezon City and suburbs, which have been and are actually being leased to tenants for at least ten years, is hereby authorized: Provided , That such lands shall have at least fifty houses of tenants erected thereon.\n\"Sec. 2. The Land Tenure Administration shall institute the necessary expropriation proceedings before the competent court.\""}},{"id":"PH-H2075-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The title of said Act, as amended, is further amended to read as follows:\n\"An Act providing for the expropriation of landed estates or haciendas or lands which formerly formed part thereof or any piece of land in the City of Manila, Quezon City and suburbs, their subdivision into small lots, and the sale of such lots at cost or their lease on reasonable terms, and for other purposes.\""}},{"id":"PH-H2075-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Ejectment proceedings against any tenant or occupant of lands authorized to be expropriated under Republic Act Numbered Eleven hundred and sixty-two, as amended, wherein no complaint for expropriation has yet been filed in the competent court, shall continue to be suspended until the thirtieth of June, nineteen hundred and sixty under the conditions set forth in section five of said Act."}},{"id":"PH-H2075-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Certain Sections of Republic Act Numbered Eleven Hundred and Sixty-Two, as Amended, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2076"] = {"id":"PH-H2076","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2343_1959.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act to Amend Certain Sections of Commonwealth Act Numbered Four Hundred Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended, and for Other Purposes","orig":"An Act to Amend Certain Sections of Commonwealth Act Numbered Four Hundred Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2343","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2343_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2076-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-one of Commonwealth Act Numbered Four hundred sixty-six, as amended by Republic Act Numbered Eighty-two, is hereby further amended to read as follows:\n\"Sec. 21. Rates of tax on citizens or residents.There shall be levied, collected, and paid annually upon the entire net income received in the preceding taxable year from all source by every individual, a citizen or resident of the Philippines, a tax equal to the sum of the following:\n\"Three per centum per annum upon the amount by which such total net income does not exceed two thousand pesos;\n\"Six per centum per annum upon the amount by which such total net income exceeds two thousand pesos and does not exceed four thousand pesos;\n\"Nine per centum per annum upon the amount by which such total net income exceeds four thousand pesos and does not exceed six thousand pesos;\n\"Sixteen per centum per annum upon the amount by which such total net income exceeds six thousand pesos and does not exceed eight thousand pesos;\n\"Twenty per centum per annum upon the amount by which such total net income exceeds eight thousand pesos and does not exceed ten thousand pesos;\n\"Twenty-four per centum per annum upon the amount by which such total net income exceeds ten thousand pesos and does not exceed twenty thousand pesos;\n\"Thirty per centum per annum upon the amount by which such total net income exceeds twenty thousand pesos and does not exceed thirty thousand pesos;\n\"Thirty-six per centum per annum upon the amount by which such total net income exceeds thirty thousand pesos and does not exceed thirty thousand pesos;\n\"Forty per centum per annum upon the amount by which such total net income exceeds forty thousand pesos and does not exceed fifty thousand pesos;\n\"Forty-two per centum per annum upon the amount by which such total net income exceeds fifty thousand pesos and does not exceed sixty thousand pesos;\n\"Forty-four per centum per annum upon the amount by which such total net income exceeds sixty thousand pesos and does not exceed seventy thousand pesos;\n\"Forty-six per centum per annum upon the amount by which such total net income exceeds seventy thousand pesos and does not exceed eighty thousand pesos;\n\"Forty-eight per centum per annum upon the amount by which such total net income exceeds eighty thousand pesos and does not exceed ninety thousand pesos;\n\"Fifty per centum per annum upon the amount by which such total net income exceeds ninety thousand pesos and does not exceed one hundred thousand pesos;\n\"Fifty-two per centum per annum upon the amount by which such total net income exceeds one hundred thousand pesos and does not exceed one hundred and twenty thousand pesos;\n\"Fifty-three per centum per annum upon the amount by which such total net income exceeds one hundred and twenty thousand pesos and does not exceed one hundred and forty thousand pesos;\n\"Fifty-four per centum per annum upon the amount by which such total net income exceeds one hundred and forty thousand pesos and does not exceed one hundred and sixty thousand pesos;\n\"Fifty-five per centum per annum upon the amount by which such total net income exceeds one hundred and sixty thousand pesos and does not exceed two hundred thousand pesos;\n\"Fifty-six per centum per annum upon the amount by which such total net income exceeds two hundred thousand pesos and does not exceed two hundred fifty thousand pesos;\n\"Fifty-seven per centum per annum upon the amount by which such total net income exceeds two hundred and fifty thousand pesos and does not exceed three hundred thousand pesos;\n\"Fifty-eight per centum per annum upon the amount by which such total net income exceeds three hundred thousand pesos and does not exceed four hundred thousand pesos;\n\"Fifty-nine per centum per annum upon the amount by which such total net income exceeds four hundred thousand pesos and does not exceed five hundred thousand pesos; and \"Sixty per centum per annum upon the amount by which such total net income exceeds five hundred thousand pesos.\""}},{"id":"PH-H2076-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section twenty-two of Commonwealth Act Numbered Four hundred sixty-six, as amended, is hereby further amended to read as follows:\n\"Sec. 22. Tax on nonresident alien individual. (a) Non- resident alien engaged in trade or business within the Philippines. There shall be levied, collected, and paid for each taxable year upon the entire net income received from all sources within the Philippines by every non- resident alien individual engaged in trade or business with- in the Philippines the tax imposed by section twenty-one.\n\"(b) Non resident alien not engaged in trade or business within the Philippines. There shall be levied, collected and paid for each taxable year upon the entire income received from all sources within the Philippines by every nonresident alien individual not engaged in trade or business within the Philippines as interest, dividends, rents, salaries, wages, premiums, annuities, compensations, remunerations, emoluments, or other fixed or determinable annual or periodical gains, capital gains, profits, and income, a tax equal to twenty per centum of such income: Provided , That if the total income received by such non- resident alien individual from all sources within the Philippines exceeds twenty-three thousand eight hundred pesos, the rates established in section twenty-one shall apply, but in no case shall the tax imposed under this subsection be less than twenty per centum of the total income.\""}},{"id":"PH-H2076-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Subsections (b) and (c) of section twenty-three of Commonwealth Act Numbered Four hundred sixty-six are amended to read as follows:\n\"(b) Personal exemption of married persons or heads of family. The sum of three thousand pesos, if the person making the return is a married man or a married woman or the head of a family: Provided , That only one exemption of three thousand pesos shall be made from the aggregate income of both husband and wife when not legally separated. For the purpose of this section, the term 'head of family includes an unmarried man or woman with one or both parents, or one or more brothers or sisters, or one or more legitimate, recognized natural, or adopted children living with and dependent upon him or her for their chief support where such brothers, sisters, or children are not more than twenty-three years of age, unmarried, and not gainfully employed, or where such children are incapable of self-support because mentally or physically defective.\n\"(c) Additional exemption for dependents. The sum or one thousand pesos for each legitimate, recognized natural, or adopted child, wholly dependent upon and living with the taxpayer if such dependents are not more than twenty-three years of age, unmarried, and not gainfully employed or incapable of self-support because mentally or physically defective. The additional exemption under this subsection shall be allowed only if the person making the return is the head of the family.\""}},{"id":"PH-H2076-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section twenty-four of Commonwealth Act Numbered Four hundred sixty-six, as amended, is further amended to read as follows:\n\"Sec. 24. Rate of tax on corporations.(a) Tax on domestic corporations. In general there shall be levied, collected, and paid annually upon the total net income received in the preceding taxable year from all sources by every corporation organized in, or existing under the laws of the Philippines, no matter how created or organized, but not including duly registered general copartnerships (companias colectivas), domestic life insurance companies and foreign life insurance companies doing business in the Philippines, a tax upon such income equal to the sum of the following:\n\"Twenty-two per centum upon the amount by which such total net income does not exceed one hundred thousand pesos; and \"Thirty per centum upon the amount by which such total net income exceeds one hundred thousand pesos; and a like tax shall be levied, collected, and paid annually upon the total net income received in the preceding taxable year from all sources within the Philippines by every corporation organized, authorized, or existing under the laws of any foreign country: Provided , however , That building and loan associations operating as such in accordance with sections one hundred and seventy-one to one hundred and ninety of the Corporation Law, as amended, as well as private educational institutions, shall pay a tax of twelve per centum and ten per centum, respectively, on their total net income: And provided, further, That in the case of dividends received by a domestic or resident foreign corporation from a domestic corporation liable to tax under this Chapter or from a domestic corporation engaged in a new and necessary industry, as defined under Republic Act Numbered Nine hundred and one, only twenty-five per centum thereof shall be returnable for purposes of the tax imposed by this section.\n\"(b) Tax on foreign corporations.(1) Nonresident corporations. There shall be levied, collected, and paid for each taxable year, in lieu of the tax imposed by the preceding paragraph, upon the amount received by every foreign corporation not engaged in trade or business within the Philippines from all sources within the Philippines, as interest, dividends, rents, salaries, wages, premiums, annuities, compensations, remunerations, emoluments, or other fixed or determinable annual or periodical gains, profits, and income, a tax equal to thirty per centum of such amount.\n\"(2) Resident corporations. A foreign corporation engaged in trade or business within the Philippines (except foreign life insurance companies) shall be taxable as provided in subsection (a) of this section.\n\"(c) Rate of tax on life insurance companies. There shall be levied, assessed, collected and paid annually from every life insurance company organized in or existing under the laws of the Philippines, or foreign life insurance company authorized to carry on business in the Philippines, but not including purely cooperative companies or associations as defined in section two hundred fifty-five of this Code, on the total investment income received by such company during the preceding taxable year from interest, dividends, and rents from all sources, whether from or without the Philippines, a tax of six and one-half per centum upon such income: Provided , however , That foreign life insurance companies not doing business in the Philippines shall, on any investment income received by them from the Philippines, be subject to tax as any other foreign corporation.\n\"The total net investment income of domestic life insurance companies is the gross investment income received during the taxable year from rents, dividends, and interest less deductions for real estate expenses, depreciation, interest paid within the taxable year on its indebtedness, except on indebtedness incurred to purchase or carry obligation the interest upon which is wholly exempt from taxation under existing laws, and such investment expenses paid during the taxable year as are ordinary and necessary in the conduct of the investments; and the total net in- vestment income of foreign life insurance companies doing business in the Philippines is that portion of their gross world investment income which bears the same ratio to such income as their total Philippine reserve bears to their total world reserve less that portion of their total world investment expenses which bear the same ratio to such expenses as their total Philippine investment income bears to their total world investment income.\""}},{"id":"PH-H2076-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Subsection (i) of section forty-five of Commonwealth Act Numbered Four hundred sixty-six, as amended, is hereby further amended to read as follows:\n\"(c) When to file. The return shall be filed on or before of fifteenth day or April of each year, covering income of the preceding calendar year, or within the extension which may be granted by the Commissioner of Internal Revenue as herein set forth.\""}},{"id":"PH-H2076-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Subsections (b) and (d) of section forty-six of Commonwealth Act Numbered Four hundred sixty-six, as amended, are hereby further amended to read as follows:\n\"(b) When to file. The return shall be filed on or before the fifteenth day of April of each year for the preceding calendar year, or if the corporation has designated a fiscal year, on or before the fifteenth of the fourth month following the close of such fiscal year.\n\"(d) Fiscal year of corporations. Every corporation subject to tax, including duly registered general copartnerships, may designate the last day of any month in the year as the day of the closing of its fiscal year, and shall be entitled to have the tax payable by it computed upon the basis of the net income ascertained as herein provided for the year ending on the day so designated in the year preceding the date of assessment instead of upon the basis of the net income for the calendar year preceding the date of assessment; and it shall give notice of the day it has thus designated as the closing of its fiscal year to the Commissioner of Internal Revenue at any time not less than thirty days prior to the fifteenth day of April of the year in which its return would be filed if made upon the basis of the calendar year.\""}},{"id":"PH-H2076-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section forty-seven of Commonwealth Act Numbered Four hundred sixty-six, as amended, is hereby further amended to read as follows:\n\"Sec. 47. Extension of time to file returns. The Commissioner of Internal Revenue may, in meritorious cases, grant a reasonable extension of time for filing returns of income subject to the provisions of section fifty-one of this Code.\""}},{"id":"PH-H2076-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section fifty-one of Commonwealth Act Numbered Four hundred sixty-six, as amended, is hereby further amended to read as follows:\n\"Sec. 51. Payment and assessment of income tax. (a) Payment of tax. (1) In general. The total amount of tax imposed by this Title shall be paid at the time the return is filed but not later than the fifteenth day of April following the close of the calendar year, or, if the return is made on the basis of a fiscal year, then not later than the fifteenth day of the fourth month following the close of the fiscal year. Such tax shall be paid by the person subject thereto, and in the case of a corporation by the President, vice-president, or other responsible officer thereof: Provided , That if in any preceding year, the payer was entitled to a refund of any amount thereof, if not yet refunded, it may be deducted from the amount of tax to be paid.\n\"If the return is filed after the time prescribed by law (including cases in which an extension of time for filing the return has been granted under section forty-seven of this Code), there shall be paid at the time of such filing the tax or installment which would have been payable on or before such time if the return had been filed within the time prescribed by law, and the remaining installment shall be paid at the time at which, and in the amount in which, it would have been payable if the return had been so filed, subject to the payment of interest at twelve per centum per annum from the original due date.\n\"(2) Installment payments. When the tax due is in excess of five hundred pesos, the taxpayer may elect to pay the tax in two equal installments, in which case, the first installment shall be paid on or before the date pre- scribed in the preceding paragraph and the second installment, on or before the fifteenth day of July following the close of the calendar year, or on or before the fifteenth day of the seventh month following the close of the fiscal year, as the case may be. If any installment is not paid on or before the date fixed for its payment, the whole amount of the tax unpaid becomes due and payable together with the delinquency penalties.\n\"(b) Assessment and payment of deficiency tax . After the return is filed, the Commissioner of Internal Revenue shall examine it and assess the correct amount of the tax. The tax or deficiency in tax so discovered shall be paid upon notice and demand from the Commissioner of Internal Revenue.\n\"In case a person fails to make and file a return or list at the time prescribed by law, or makes, willfully or otherwise, a false or fraudulent return or list, the Commissioner of Internal Revenue shall make the return from his own knowledge and from such information as he can obtain through testimony or otherwise. In any such case, the Commissioner of Internal Revenue may make a return or amend any return and any return so made or amended shall be prima facie good and sufficient for all legal purposes, unless the taxpayer can prove the contrary under proper proceedings to be determined by the Commissioner of Internal Revenue.\n\"(c) Definition of deficiency. As used in this Chapter in respect of a tax imposed by this Title, the term 'deficiency' means;\n\"(1) The amount by which the tax imposed by this Title exceeds the amount shown as the tax by the taxpayer upon his return; but the amount so shown on the return shall first be increased by the amounts previously assessed (or collected without assessment) as a deficiency, and decreased by the amount previously abated, credited, returned, or otherwise in respect of such tax; or \"(2) If no amount is shown as the tax by the taxpayer upon his return, or if no return is made by the taxpayer, then the amount by which the tax exceeds the amounts previously assessed (or collected without assessment) as a deficiency; but such amounts previously assessed or collected without assessment, shall first be decreased by the amounts previously abated, credited, returned, or otherwise repaid in respect of such tax.\n\"(d) Interest on deficiency. Interest upon the amount determined as a deficiency shall be assessed at the same time as the deficiency and shall be paid upon notice and demand from the Commissioner of Internal Revenue; and shall be collected as a part of the tax, at the rate of six per centum per annum from the date prescribed for the payment of the tax (or, if the tax is paid in installments, from the date prescribed for the payment of the first installment) to the date the deficiency is assessed: Provided , That the maximum amount that may be collected as interest on deficiency shall in no case exceeded the amount corresponding to a period of three years, the present provisions regarding prescription to the contrary notwithstanding.\"\n\"(e) Additions to the tax in case of nonpayment. (1) Tax shown on the return. Where the amount deter- mined by the taxpayer as the tax imposed by this Title or any installment thereof, or any part of such amount or installment, is not paid on or before the date prescribed for its payment, there shall be collected as a part of the tax, interest upon such unpaid amount at the rate of one per centum a month from the date prescribed for its payment until it is paid: Provided , That the maximum amount that may be collected as interest on deficiency shall in no case exceed the amount corresponding to a period of three years, the present provisions regarding prescription to the contrary notwithstanding.\n\"(2) Deficiency. Where a deficiency, or any interest assessed in connection therewith under paragraph (d) of this section, or any addition to the taxes provided for in section seventy-two of this Code is not paid in full within thirty days from the date of notice and demand from the Commissioner of Internal Revenue, there shall be collected upon the unpaid amount, as part of the tax, interest at the rate of one per centum a month from the date of such notice and demand until it is paid: Provided , That the maximum amount that may be collected as interest on deficiency shall in no case exceed the amount corresponding to a period of three years, the present provisions regarding prescription to the contrary notwithstanding.\n\"(3) Surcharge. If any amount of the tax included in the notice and demand from the Commissioner of Internal Revenue is not paid in full within thirty days after such notice and demand, there shall be collected in addition to the interest prescribed herein and in paragraph (d) above and as part of the tax a surcharge of five per centum of the amount of tax unpaid.\""}},{"id":"PH-H2076-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Subsections (a)(1), (b), and (c), of section fifty-three of Commonwealth Act Numbered Four hundred sixty-six, as amended, are hereby further amended to read as follows:\n\"(a) Tax-free covenant bonds. (1) Requirement of withholding. If any case where bonds, mortgages, deeds of trust, or other similar obligations of domestic or resident foreign corporations, contain a contract or provision by which the obligor agrees to pay any portion of the tax imposed by the Title upon the obligee or to reimburse the obligee for any portion of the tax or to pay the interest without deduction for any tax which the obligor may be required or permitted to pay thereon or to retain therefrom under any law of the Philippines, or of any state or country, the obligor shall deduct and withhold a tax equal to twenty per centum of the interest upon such bonds, mortgages, deeds of trust, or other obligations, whether such interest is payable annually or at shorter or longer periods, and whether such bonds, obligations, or securities had been heretofore or are hereafter issued or marketed, and the interest thereon paid, within or without the Philippines if such interest is payable to a nonresident alien individual or to a citizen or resident of the Philippines.\n\"(b) Nonresident aliens. All persons, corporations and general copartnerships (companias colectivas), in whatever capacity acting, including lessees or mortgagors of real or personal property, trustees acting in any trust capacity, executors, administrators, receivers, conservators, fiduciaries, employers, and all officers and employees of the Government of the Philippines having the control, receipt, custody, disposal, or payment of interest, dividends, rents, salaries, wages, premiums, annuities, compensations, remunerations, emoluments, or other fixed or determinable annual or periodical gains, profits, and income of any non- resident alien individual, not engaged in trade or business within the Philippines and not having any office or place of business therein, shall (except in the cases provided for in subsection (a) of this section) deduct and withhold from such annual or periodical gains, profits, and income a tax equal to twenty per centum hereof: Provided , That no such deduction or withholding shall be required in the case of dividends paid by a foreign corporation unless (1) such corporation is engaged in trade or business within the Philippines and (2) more than eighty-five per centum of the gross income of such corporation for the three-year period ending with the close of its taxable year preceding the declaration of such dividends (or for such part of such period as the corporation has been in existence) was derived from sources within the Philippines as determined under the provisions of section thirty-seven: Provided , further, That the Commissioner of Internal Revenue may authorize such tax to be deducted and withheld from the interest upon any securities the owners of which are not known to the withholding agent.\n\"(c) Return and payment. Every person required to deduct and withhold any tax under this section shall make return thereof, in duplicate, on or before the fifteenth day of April of each year, and, on or before the time fixed by law for the payment of the tax, shall pay the amount withheld to the officer of the Government of the Philippines authorized to receive it. Every such person is made personally liable or such tax, and is indemnified against the claims and demands of any persons for the amount of any payments made in accordance with the provision of this section.\""}},{"id":"PH-H2076-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section fifty-four of Commonwealth Act Numbered Four hundred sixty-six, as amended, is hereby further amended to read as follows:\n\"Sec. 54. Payment of corporation income tax at source. In the case of foreign corporations subject to taxation under this Title not engaged in trade or business within the Philippines and not having any office or place of business therein, there shall be deducted and withheld at the source in the same manner and upon the same items as is provided in section fifty-three a tax equal to thirty per centum thereof, and such tax shall be returned and paid in the same manner and subject to the same conditions as provided in that section.\""}},{"id":"PH-H2076-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"In lieu of section three hundred sixty of Commonwealth Act Numbered Four hundred sixty-six, as amended, which has been repealed by section eight, Commonwealth Act Numbered Five hundred eighty-six, insert a new section reading as follows:\n\"Sec. 360. Disposition of proceeds of income, inheritance, and gift taxes. Two and one-half per centum of the proceeds of the tax on income and of the tax on inheritance, legacies, and other acquisitions mortis causa, as well as on gifts, shall accrue to the municipalities, and the remaining ninety-five per centum shall accrue to the National Government. The proceeds accruing to the provinces and municipalities shall be apportioned either on the basis of population as shown by the latest official census or on the total amount of the respective tax collected during the fiscal year within the respective province or municipality, whichever will render the greater share to the local government.\n\"In addition to the foregoing, whenever the total annual collection of income taxes within a municipality or provinces, as the case may be, exceeds the total collection of such taxes within such municipality or province during the fiscal year nineteen hundred fifty-nine, all the excess shall be apportioned as follows: twenty per cent to the municipality, ten per cent to the province and seventy per cent to the National Government.\n\"Such provisions of Commonwealth Act Numbered Five hundred eighty-six as may be inconsistent with the fore- going are hereby repealed.\""}},{"id":"PH-H2076-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Returns or information hereafter filed or required to be filed under Title II of Commonwealth Act Numbered Four hundred sixty-six, otherwise known as the National Internal Revenue Code, as amended, on or before the first day of March of each year shall, henceforth, be filed on or before the fifteenth day of April of each year."}},{"id":"PH-H2076-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval: Provided , That the rate hereinabove stipulated shall apply to income received from January first, nineteen hundred and fifty-nine, and for fiscal periods ending after June thirty, nineteen hundred and fifty-nine.\nApproved: June 20, 1959"}}],"pack":"ph-p29"};
  FT["PH-H2077"] = {"id":"PH-H2077","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2344_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《国家国内税收法典》第189条第1款的法案","en":"An Act to Further Amend the First Paragraph of Section One Hundred Eighty-Nine of the National Internal Revenue Code","orig":"An Act to Further Amend the First Paragraph of Section One Hundred Eighty-Nine of the National Internal Revenue Code"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2344","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2344_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2077-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of section on hundred eighty-nine of Commonwealth Act Numbered Four hundred sixty-six, otherwise known as the National Internal Revenue Code, as amended, is further amended to read as follows:\nSec. 189 . Percentage tax upon proprietors or operators of rope factories, sugar centrals, rice mills, coconut oil mills, corn mills, and desiccated coconut factories. -Proprietors or operators of rope factories, sugar centrals, rice mills, coconut oil mills, corn mills and desiccated coconut factories shall pay a tax equivalent to two per centum of the gross value in money of all the rope, sugar, rice, coconut oil, ground or milled corn, and desiccated coconut manufactured or milled by them, including the by-products of the raw materials from which the said articles are produced or manufactured, such tax to be based on the actual selling price or market value of these articles at the time they leave the factory or mill warehouse: Provided, However, That this tax shall not apply to ropes, coconut oil, and the by-products of copra from which it is produced or manufactured, and desiccated coconuts, if such ropes, oil, copra by products and desiccated coconuts shall be removed for exportation and are actually exported without returning to the Philippines, whether so exported in their original state, or as an ingredient or part of any manufactured article or product.\""}},{"id":"PH-H2077-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend the First Paragraph of Section One Hundred Eighty-Nine of the National Internal Revenue Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2078"] = {"id":"PH-H2078","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2345_1959.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Gonzalo Puyat and Sons Inc. 在菲律宾境内建设、设立、维护和运营私人固定点对点无线电台及中继与海陆移动站的临时许可的法案","en":"An Act Granting to Gonzalo Puyat and Sons Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations, with Corresponding Relay and Land and Sea Mobile Stations, for the Reception and Transmission of Radio Communication Within the Philippines","orig":"An Act Granting to Gonzalo Puyat and Sons Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations, with Corresponding Relay and Land and Sea Mobile Stations, for the Reception and Transmission of Radio Communication Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2345","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2345_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2078-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Gonzalo Puyat & Sons, Inc., its successors or assigns, a permit to construct, establish, maintain and operate in the Philippines, at such places as the said corporation may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus; each fixed point station to be further provided, according to its needs, with a suitable radio receiving and radio transmitting apparatus which shall enable the station to communicate with land and sea mobile stations located within a radius of not more than fifty kilometers of the fixed point station."}},{"id":"PH-H2078-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This permit shall continue to be in force until such time as the Government has established at the places selected by the grantee service that is similar and identical to the services to be established by the grantee under this permit, and this permit shall be null and void unless the construction of at least two of the stations allowed by this permit be begun within one year from the date of approval of this Act, and be completed within two years from said date."}},{"id":"PH-H2078-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after four years from the date of the approval of this Act the grantee shall have fulfilled said conditions or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H2078-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of any of the stations covered by this permit on lands or waters of the public domain upon such terms as he may prescribe."}},{"id":"PH-H2078-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without special assent from Congress, it being expressly understood that the purpose of this permit is to secure to the grantee the right and privilege of constructing, establishing, maintaining and operating radio communications facilities for the private interests of the grantee."}},{"id":"PH-H2078-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Under this permit, the Secretary of Public Works and Communications shall allot to the grantee frequencies and wave lengths to be used by the grantee, its successors and assigns, and the grantee shall not use frequencies and wave lengths other than those thus allotted; but, whenever necessary the grantee may use the international distress frequency of five hundred kilocycles and the high distress frequency of eight thousand two hundred eight kilocycles."}},{"id":"PH-H2078-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No fees are chargeable, as, under this permit, the corporation shall engage in communications regarding its business only."}},{"id":"PH-H2078-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall so construct and operate its radio stations as not to interfere with the operations of other radio stations maintained and operated within the Philippines."}},{"id":"PH-H2078-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee, its successors and assigns, shall hold harmless the National, provincial and municipal governments of the Philippines from all claims, accounts, demands and actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H2078-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use of possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H2078-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not lease, transfer, grant the use of, sell or assign this permit, nor the rights and privileges acquired by virtue of this permit, to any person, firm, company, corporation or any other legal or commercial entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this permit may be sold, transferred or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter to be enacted; and any person, firm, company, corporation or other legal or commercial entity to which this permit is sold, transferred or assigned shall be subject to all the conditions, terms, restrictions and limitations of this permit as fully and completely and to the same extent as if the permit had been originally granted to the said person, firm, company, corporation or other legal or commercial entity."}},{"id":"PH-H2078-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H2078-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to Gonzalo Puyat and Sons Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point Radio Stations, with Corresponding Relay and Land and Sea Mobile Stations, for the Reception and Transmission of Radio Communication Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2079"] = {"id":"PH-H2079","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2346_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权并批准将第1337号共和国法授予《晚报》出版公司的特许权转让给岛际广播公司的法案","en":"An Act Authorizing and Approving the Transfer of the Franchise Granted to the Evening News Publishing Co., Inc. by Republic Act Numbered Thirteen Hundred Thirty-Seven in Favor of the Inter-Island Broadcasting Corporation","orig":"An Act Authorizing and Approving the Transfer of the Franchise Granted to the Evening News Publishing Co., Inc. by Republic Act Numbered Thirteen Hundred Thirty-Seven in Favor of the Inter-Island Broadcasting Corporation"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2346","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2346_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2079-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The transfer of the franchise granted to the Evening News Publishing Co., Inc., by Republic Act Numbered Thirteen hundred thirty-seven in favor of the Interisland Broadcasting Corporation, together with all the rights and privileges of, including any channel and/or frequency assignments and permits that may have been granted to, the former is hereby authorized and approved: Provided, That this transfer of franchise shall be void unless the construction of at least one radio broadcasting station or one television station be begun within two years from the date of approval of this Act."}},{"id":"PH-H2079-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing and Approving the Transfer of the Franchise Granted to the Evening News Publishing Co., Inc. by Republic Act Numbered Thirteen Hundred Thirty-Seven in Favor of the Inter-Island Broadcasting Corporation","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2080"] = {"id":"PH-H2080","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2347_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第790号共和国法第1条、第2条与第4条的法案","en":"An Act to Amend Sections One, Two and Four of Republic Act Numbered Seven Hundred Ninety","orig":"An Act to Amend Sections One, Two and Four of Republic Act Numbered Seven Hundred Ninety"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2347","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2347_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2080-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one, two and four of Republic Act Numbered Seven hundred ninety are amended to read as follows:\nSec. 1 . There is hereby granted to the Acoje Mining Co., Inc., its successors or assigns, a temporary permit to construct, maintain and operate in the Philippines, at such places as the said grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and private coastal radio stations, as well as point-to-point field stations for new operations and associated companies, mobile land stations, mobile sea stations, mobile air stations and communications from point-to-point ground, land point to mobile air, land or sea, mobile air to air, sea or land and mobile sea to air, sea or land, for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus. Said grantee is authorized to use any combination of these facilities for the efficiency and safety of its operations.\nSec. 2 . The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and private coastal radio stations, as well as point-to-point field stations for new operations and associated companies, mobile land stations, mobile sea stations, mobile air stations and communications from point-to-point ground, land point to mobile air, land or sea, mobile air to air, sea or land and mobile sea to air, sea or land, or any of them on lands of the public domain upon such terms as he may prescribe.\nSec. 4 . The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this permit is to secure to the grantee the right to construct, maintain and operate private fixed point-to-point and private coastal radio stations, as well as point-to-point field stations for new operations and associated companies, mobile land stations, mobile sea stations, mobile air stations and communications from point-to-point ground, land point to mobile air, land or sea, mobile air, sea or land and mobile sea to air, sea or land, in such places within the Philippines as the interest of the company and of its trade and business may justify.\""}},{"id":"PH-H2080-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Sections One, Two and Four of Republic Act Numbered Seven Hundred Ninety","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2081"] = {"id":"PH-H2081","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2348_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授权返还依第41号联邦法捐赠给国家政府的土地，规定其处分办法并为其他目的法案","en":"An Act to Authorize the Reconveyance of Lands Donated to the National Government Under Commonwealth Act Numbered Forty-One, to Provide for the Disposition Thereof, and for Other Purposes","orig":"An Act to Authorize the Reconveyance of Lands Donated to the National Government Under Commonwealth Act Numbered Forty-One, to Provide for the Disposition Thereof, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2348","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2348_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2081-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Director of Lands is hereby authorized to donate back to the respective provinces, cities and municipalities which donated the same, such lands to include government buildings and other installations thereon under Commonwealth Act Numbered Forty-one, entitled \"An Act authorizing the provincial, municipal and city governments to appropriate funds to purchase real or personal property and to donate the same to the National Government for the use of the Philippine Army,\" which may be declared by the President of the Philippines as no longer needed for military purposes."}},{"id":"PH-H2081-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The respective provincial and municipal boards or councils are authorized to dispose of the same by sale to persons qualified to acquire agricultural public lands under the provisions of Commonwealth Act Numbered One hundred and forty-one, commonly known as the Public Land Act, for such price as they may determine, considering the current market value thereof: Provided, However, That if the acquisition thereof was by eminent domain, first priority shall be given to former owners, their heirs or legal representatives at the same cost when acquired from them, and thereafter the bona fide occupants of such lands, and war veterans, in the order named: Provided, further, That should government buildings and other installations still fit for use and occupation, be still standing on such lands, the respective provinces, cities or municipalities, at their discretion, may retain ownership of the buildings and other installations and so much of the premises as would be necessary for the use and occupation for governmental purposes, or convey by sale at a fair market price the land acquired by voluntary transaction and such buildings and other installations with the land to the persons hereinbefore named in this section: And Provided, finally, That in cases where the lands used as cadre site were gratuitously donated by the owner or owners to the municipal, provincial or city governments which in turn donated same to the National Government, said lands shall be reconveyed to the respective owner or owners by gratuitous donation."}},{"id":"PH-H2081-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All provisions of laws, executive orders, rules and regulations or parts thereof inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H2081-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Authorize the Reconveyance of Lands Donated to the National Government Under Commonwealth Act Numbered Forty-One, to Provide for the Disposition Thereof, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2082"] = {"id":"PH-H2082","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2349_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Leon Arcinas在巴拉望省Cuyo市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting Leon Arcinas a Franchise for an Electric Light, Heat and Power System in the Municipality of Cuyo, Province of Palawan","orig":"An Act Granting Leon Arcinas a Franchise for an Electric Light, Heat and Power System in the Municipality of Cuyo, Province of Palawan"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2349","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2349_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2082-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Leon Arcinas, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Cuyo, Province of Palawan."}},{"id":"PH-H2082-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2082-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and shall turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2082-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Leon Arcinas a Franchise for an Electric Light, Heat and Power System in the Municipality of Cuyo, Province of Palawan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2083"] = {"id":"PH-H2083","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2350_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Eight Million Two Hundred Thirty-Eight Thousand Three Hundred Four Pesos for the Current Operation and Maintenance of the Three Thousand Five Hundred Twenty Additional Extension Classes Organized in August and November, Nineteen Hundred and Fifty-Eight","orig":"An Act Appropriating the Sum of Eight Million Two Hundred Thirty-Eight Thousand Three Hundred Four Pesos for the Current Operation and Maintenance of the Three Thousand Five Hundred Twenty Additional Extension Classes Organized in August and November, Nineteen Hundred and Fifty-Eight"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2350","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2350_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2083-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of eight million two hundred thirty-eight thousand three hundred four pesos, or so much thereof as may be necessary, is thereby appropriated, out of any funds in the National Treasury not otherwise appropriated for the operation and maintenance of the three thousand five hundred twenty additional elementary classes organized in August and November, nineteen hundred and fifty-eight, up to the end of the current fiscal year, in the following manner and form:\nSalaries of 3,500 elementary grades teachers, at ₱1,920 per annum for eleven (11) months ₱6,160,000 Salaries of 20 elementary grades teachers, at ₱1,920 per annum for eight (8) months 25,600 Life insurance premiums, government share, at three per centum of salary 185,568 Retirement insurance premiums, government share, at six per centum of salary 371,136 For the purchase of textbooks, at ₱225 per class 792,000 For the purchase of furniture and equipment, at ₱200 per class 704,000 Total --------------- ₱8,238,304 ========="}},{"id":"PH-H2083-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29"};
  FT["PH-H2084"] = {"id":"PH-H2084","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2351_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第901号共和国法，使新兴与必要产业的所得全额缴纳所得税；规范此类产业进口税收豁免的给予；规定违反或滥用该税收豁免的处罚并为其他目的","en":"An Act Amending Republic Act Numbered Nine Hundred One so as to Subject the Income of New and Necessary Industries to the Full Payment of the Income Tax; to Regulate the Grant of Tax Exemption on Importations by Such Industries; to Provide Penalties for the Violation and/or Misuse of the Grant of Such Tax Exemption, and for Other Purposes","orig":"An Act Amending Republic Act Numbered Nine Hundred One so as to Subject the Income of New and Necessary Industries to the Full Payment of the Income Tax; to Regulate the Grant of Tax Exemption on Importations by Such Industries; to Provide Penalties for the Violation and/or Misuse of the Grant of Such Tax Exemption, and for Other Purposes"},"level":"law","status":"active","topics":["tax","trade","criminal"],"docNumber":"Republic Act No. 2351","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2351_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2084-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Nine hundred one is amended to read as follows:\nSec. 1 . Any person, partnership, company or corporation who or which, subsequent to the approval of this Act, shall engage in a new and necessary industry shall be entitled to exemption until December thirty-one, nineteen hundred and fifty-eight from payment of all taxes directly payable by such person, partnership, company or corporation in respect to said industry and to a diminishing exemption during the following four years as follows: ninety per centum of all said taxes during the period from January first to December thirty-one, nineteen hundred and fifty-nine; seventy-five per centum of all said taxes during the period from January first to December thirtyone, nineteen hundred and sixty; fifty per centum of all said taxes during the period from January first to December thirty-one, nineteen hundred and sixty-one; and ten per centum of all said taxes during the period from January first to December thirty-one, nineteen hundred and sixtytwo; after which such person, partnership, company, or corporation shall be liable in full to all taxes: Provided, That income received by such person, partnership, company or corporation from July first, nineteen hundred and fifty-nine, shall be subject to the full tax provided in Title II of the National Internal Revenue Code: Provided, further, That machinery and spare parts thereof, and raw materials of tax-exempt industries shall be exempted from taxes, except the special import tax and new taxes which may hereafter be imposed, if the Secretary of Finance, the Secretary of Commerce and Industry and the Chairman of the National Economic Council, after investigation, find (a) that, considering the capacity of the plant or factory concerned, the said machinery and spare parts, and raw materials are actually needed and will be used exclusively by the grantee in the manufacture of articles covered by the tax exemption and (b) that the foreign exchange allocation and related documents covering the importation are in the name of the importing tax-exempt industry to whom the goods shall be delivered directly by the customs authorities: Provided, further, That the tax exemption provided for in this Act shall not include any company or person engaged in the processing of oil, gasoline, lubricants and other similar fuels and by-products: Provided, still further, That those who or which were declared engaged in a new and necessary industry under the provisions of Republic Act Numbered Thirty-five and still enjoying exemption thereunder from all internal revenue taxes for a period of four years, shall automatically be entitled to exemption under this Act, but in no case shall the total number of years of their exemption, both under Republic Act Numbered Thirty-five and this Act, be for more than ten years. A grantee of tax exemption under Republic Act Numbered Thirty-five whose exemption has expired prior to the approval of this Act shall, upon application filed within three months from the approval of this Act and if found to be still qualified under the provisions of the law and regulations pursuant to which its exemption was granted, be entitled to tax exemption under this Act for a period of six years from the approval hereof.\""}},{"id":"PH-H2084-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A new section to be known and cited as section 11-A is hereby inserted in the same Act to read as follows:\nSec. 11-A . Any grantee under Republic Act Numbered Thirty-five and this Act, who shall make use of the privileges granted thereunder or under any other law, rule or regulation for purposes other than those for which such privileges were granted shall be penalized with imprisonment of not less than five years but not exceeding ten years and fine of not less than eight thousand pesos but not exceeding two hundred thousand pesos, and in addition, such violation shall ipso facto cause forfeiture of the exemption.\n\"Any officer or employee of the Government who shall connive, abet, or tolerate the violation of the provisions of this Act or any rules or regulations promulgated in accordance therewith shall suffer the penalties in the preceding paragraph including perpetual disqualification to hold public office.\n\"Any person who shall connive with the grantee of tax exemption shall be penalized accordingly as co-principal. In case the grantee is a juridical person, the officials who consented to the offense or knowing, did not register objection shall be the persons liable.\n\"Any provision of law to the contrary notwithstanding, a grantee of the tax exemption privileges who shall purchase goods or commodities while in transit from any person or corporation which originally placed the order for the importation thereof, shall be considered the importer of such goods or commodities and shall be subject to all taxes imposed on such importation.\n\"No provision of this Act shall be interpreted to condone any previous act in violation of existing law, rules or regulations.\""}},{"id":"PH-H2084-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered Nine Hundred One so as to Subject the Income of New and Necessary Industries to the Full Payment of the Income Tax; to Regulate the Grant of Tax Exemption on Importations by Such Industries; to Provide Penalties for the Violation and/or Misuse of the Grant of Such Tax Exemption, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2085"] = {"id":"PH-H2085","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2352_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"撤销某些特别进口税豁免（包括免税产业享有的豁免），为此废止第1394号共和国法第6条及第901号共和国法关于特别进口税的相关规定","en":"An Act Revoking Some Exemptions from the Payment of the Special Import Tax, Including that Enjoyed by Tax-Exempt Industries, Repealing for This Purpose Section Six of Republic Act Numbered Thirteen Hundred and Ninety-Four and the Pertinent Provision of Republic Act Numbered Nine Hundred One Insofar as it Refers to the Special Import Tax","orig":"An Act Revoking Some Exemptions from the Payment of the Special Import Tax, Including that Enjoyed by Tax-Exempt Industries, Repealing for This Purpose Section Six of Republic Act Numbered Thirteen Hundred and Ninety-Four and the Pertinent Provision of Republic Act Numbered Nine Hundred One Insofar as it Refers to the Special Import Tax"},"level":"law","status":"active","topics":["tax","trade"],"docNumber":"Republic Act No. 2352","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2352_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2085-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section six of Republic Act Numbered Thirteen hundred and ninety-four is hereby repealed with the exception of drugs and medicines, and medical, dental and hospital supplies, enumerated as follows:\nDrugs and Medicines\n1. Amebacides, except emetine preparations.\n2. Amino acid preparations and analgesic poultries.\n3. Anaesthetics, all types.\n4. Antiacids, absorbents, and preparations.\n5. Antibiotics and preparations, except dosage forms of penicillin, streptomycin and/or combinations.\n6. Anticholinergic preparations.\n7. Anticoagulants.\n8. Anti-leprosy preparations.\n9. Antimalarials, except quinine preparations.\n10. Antispasmodic, anticonvulsant, and sympathomimetic preparations.\n11. Antitoxins, vaccines, sera, toxoids and antigens.\n12. Homogenized baby foods.\n13. Diagnostic and laboratory reagents.\n14. Digitalis and preparations.\n15. Drugs (crude or otherwise), chemicals (simple or compound) for pharmaceutical manufacture.\n16. Drugs and medicines for the use of the dental and veterinary professions.\n17. Ergot and preparations.\n18. Fumigants, disinfectants, and preparations.\n19. Gland products and synthetic substitutes.\n20. Hemostatics for topical use.\n21. Hexylresorcinol preparations.\n22. Insulin, all forms.\n23. Liver extract.\n24. Mercurial diuretics.\n25. Narcotics and hypnotics, natural or synthetic, and preparations.\n26. Pharmaceutical glassware and containers not manufactured locally.\n27. Plasma.\n28. Saccharin and substitutes.\n29. Salt substitutes.\n30. Steroids and preparations.\n31. Surgical antiseptics.\nMedical, Dental and Hospital Supplies\n1. Adhesives, plasters, badges, gauzes, and dressings.\n2. Cottons, absorbents or synthetic substitutes.\n3. Dental instruments, equipment and supplies.\n4. Diagnostic instruments.\n5. Hospital and surgical rubber goods including catheters.\n6. Electro-medical therapy equipment.\n7. Optometric instruments and supplies.\n8. Surgical instruments, equipment and supplies, including operating lights and sterilizers, except examining and treatment tables.\n9. X-Ray equipment, films and supplies.\n10. Radium and radioactive materials for therapy.\n11. Spare parts for dental, electro-medical, therapy and X-Ray equipment.\n12. Supplies and equipment to be used exclusively by the Blood Bank of the Philippine Red Cross.\n13. New well-tested drugs not yet commercially available authorized by the Secretary of Health each year upon the recommendation of the Philippine Medical Association and the Philippine Federation of Private Medical Practitioners. The Secretary of Commerce and Industry shall certify as to the drugs not being commercially available. fertilizers when imported by planters or farmers directly or through their cooperatives; textbooks, reference books, and supplementary readers approved by the Board on Textbooks and/or established public, or private educational institutions upon certification by the Secretary of the Department of Education; paper and newsprint imported by publishers for their exclusive use in the publication of books, pamphlets, magazines, and newspapers; canned salmon and sardines; unassembled air pressure kerosene lamps; explosives and dynamite for mining purposes; and articles or containers used, including materials for the manufacture of tin containers used by the importer himself in the manufacture or preparation of local products for consignment or export abroad."}},{"id":"PH-H2085-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The exemption enjoyed by the tax-exempt industries under the provisions of Republic Act Numbered Nine hundred one, insofar as it refers to special import tax, is hereby revoked."}},{"id":"PH-H2085-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Revoking Some Exemptions from the Payment of the Special Import Tax, Including that Enjoyed by Tax-Exempt Industries, Repealing for This Purpose Section Six of Republic Act Numbered Thirteen Hundred and Ninety-Four and the Pertinent Provision of Republic Act Numbered Nine Hundred One Insofar as it Refers to the Special Import Tax","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2086"] = {"id":"PH-H2086","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2353_1959.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"进一步修订第1392号共和国法（经第1768号共和国法修正）第1条，该法对完全以菲律宾苎麻纤维制成的纺织品免征关税与特别进口税，以激励苎麻产业发展","en":"An Act to Further Amend Section One of Republic Act Numbered One Thousand Three Hundred Ninety-Two, as Amended by Republic Act Numbered One Thousand Seven Hundred Sixty-Eight, Entitled “An Act Exempting Textiles Made of One Hundred Per Cent Philippine Ramie Fiber from the Payment of Duty and the Special Import Tax to Provide Incentives for the Development of the Ramie Industry”","orig":"An Act to Further Amend Section One of Republic Act Numbered One Thousand Three Hundred Ninety-Two, as Amended by Republic Act Numbered One Thousand Seven Hundred Sixty-Eight, Entitled “An Act Exempting Textiles Made of One Hundred Per Cent Philippine Ramie Fiber from the Payment of Duty and the Special Import Tax to Provide Incentives for the Development of the Ramie Industry”"},"level":"law","status":"active","topics":["tax","trade"],"docNumber":"Republic Act No. 2353","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2353_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2086-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered One thousand three hundred ninety-two, as amended by Republic Act Numbered One thousand seven hundred sixty-eight, is further amended to read as follows:"}},{"id":"PH-H2086-A1-d2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Ramie threads, yarns, textiles, and industrial fabrics hereinafter also called ramie goods, when processed abroad from one hundred per cent ramie fiber grown in the Philippines and bought direct from the farmer-producers or from any of their cooperatives by any government agency designated by the President of the Philippines and by it exported abroad in exchange therefor when their importation is made through the government agency so designated by the President shall be exempt from the payment of customs duties under the tariff laws in force: Provided, That such tax-exempt importation herein contemplated shall be allocated proportionately among the original farmer-producers or any of their cooperatives from whom the government agency herein specified obtained the ramie fiber for processing abroad: Provided, further, That only ramie fibers produced in excess of the local requirement of ten thousand eight hundred (10,800) two-picul bales per annum plus any portion of the said ten thousand eight hundred (10,800) two-picul bales which cannot be absorbed by local manufacturers due to unforeseen or fortuitous events shall be entitled to the benefits of this Act: And Provided, finally, That should existing facilities of local manufacturers either through expansion or construction of new mills or otherwise, require ramie fibers in excess of ten thousand eight hundred (10,800) two-picul bales, and the same is certified to by the National Economic Council, such excess requirement should first be filled up before the benefits of this Act could be availed of.\n\"The exemption above granted shall cease on December thirty-first, nineteen hundred sixty or at any earlier date upon proclamation by the President, upon recommendation of the National Economic Council, to the effect that sufficient degumming, spinning and/or weaving mills to process the entire production of ramie fiber have been established in the country.\""},"dupIndex":2},{"id":"PH-H2086-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"No dollar allocation shall be granted to the producers, their cooperatives or to the Agricultural Credit and Cooperative Financing Administration for the purpose of carrying out the purposes of this Act unless upon certification by the Philippine Embassy in Japan that no processor in Japan agrees to process Philippine ramie fiber unless paid in dollars."}},{"id":"PH-H2086-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The title of Republic Act Numbered One thousand three hundred ninety-two is amended to read as follows:\n\"An Act exempting textiles made of one hundred per cent Philippine ramie fiber from the payment of duty and to provide incentives for the development of the ramie industry.\""}},{"id":"PH-H2086-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Section One of Republic Act Numbered One Thousand Three Hundred Ninety-Two, as Amended by Republic Act Numbered One Thousand Seven Hundred Sixty-Eight, Entitled “An Act Exempting Textiles Made of One Hundred Per Cent Philippine Ramie Fiber from the Payment of Duty and the Special Import Tax to Provide Incentives for the Development of the Ramie Industry”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2087"] = {"id":"PH-H2087","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2354_1959.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Luzonian Colleges, Inc. 在菲律宾为教育、科学、文化与商业目的建设、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting the Luzonian Colleges, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations and Stations for Television in the Philippines for Educational, Scientific, Cultural and Commercial Purposes","orig":"An Act Granting the Luzonian Colleges, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations and Stations for Television in the Philippines for Educational, Scientific, Cultural and Commercial Purposes"},"level":"law","status":"active","topics":["investment","trade","education"],"docNumber":"Republic Act No. 2354","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2354_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2087-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution as well as of Act Numbered Three thousand eight hundred forty-six entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, not inconsistent with this Act, the Luzonian Colleges, Inc., is hereby granted a franchise to construct, maintain and operate radio broadcasting stations and stations for television in the Philippines for educational, scientific and cultural as well as for commercial purposes and in the public interest."}},{"id":"PH-H2087-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the said stations shall be put in operation, and is granted upon the express condition that the same shall be void unless the construction of at least one radio broadcasting station or one station for television be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H2087-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall provided adequate public service time to enable the government, thru its stations, to reach the population on important issues, shall assist in the functions of public information and education, shall conform to the ethics of honest enterprise, and shall not use its stations for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health and morals, or incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H2087-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee’s radio broadcasting stations and stations for television shall not be put in actual operations until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used under this franchise and issued to the grantee license for such use."}},{"id":"PH-H2087-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The radio broadcasting stations and stations for television of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing radio stations and stations for television and to permit the expansion of the grantee’s services."}},{"id":"PH-H2087-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H2087-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on its real estate, buildings, and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. It shall be liable further to pay all other taxes as provided in the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H2087-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance of this franchise shall be given in writing by the grantee within six months after the approval of this Act. When so accepted, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H2087-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall file a bond in the amount of ten thousand pesos to guarantee the full compliance with and fulfillment of the conditions under which this franchise is granted. If after two years from the date of acceptance of this franchise, the grantee shall have fulfilled said conditions or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H2087-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast may cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral."}},{"id":"PH-H2087-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and as completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H2087-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Wherever in this Act the term \"grantee\" is used, it shall be held and understood to mean and represent the Luzonian Colleges, Inc., its representatives, successors and assigns."}},{"id":"PH-H2087-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H2087-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Luzonian Colleges, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations and Stations for Television in the Philippines for Educational, Scientific, Cultural and Commercial Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2088"] = {"id":"PH-H2088","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2355_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在萨马省Guiuan市镇设立结核病馆的法案","en":"An Act Providing for the Establishment of a Tuberculosis Pavilion in the Municipality of Guiuan, Province of Samar","orig":"An Act Providing for the Establishment of a Tuberculosis Pavilion in the Municipality of Guiuan, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2355","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2355_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2088-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Health Services, a tuberculosis pavilion in the Municipality of Guiuan, Province of Samar, to be known as the Guiuan Tuberculosis Pavilion."}},{"id":"PH-H2088-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H2088-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Tuberculosis Pavilion in the Municipality of Guiuan, Province of Samar","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2089"] = {"id":"PH-H2089","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2356_1959.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 L. S. Sarmiento and Co., Inc. 在菲律宾境内建设、设立、维护和运营私人固定点对点与海岸无线电台的临时许可的法案","en":"An Act Granting L. S. Sarmiento &amp; Co., Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting L. S. Sarmiento &amp; Co., Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2356","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2356_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2089-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to L. S. Sarmiento & Co., Inc., a temporary permit to construct, establish, maintain and operate in the Philippines, at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and private coastal radio stations, for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H2089-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and private coastal radio stations or any of them on lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H2089-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction of at least one of the said stations be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H2089-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunication in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate private fixed point-to-point and private coastal radio stations in such places within the Philippines as the interest of the grantee and of its trade and business may justify."}},{"id":"PH-H2089-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted."}},{"id":"PH-H2089-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder, but the grantee may use the international distress frequency of five hundred kilocycles and the high distress frequency of eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H2089-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No fees are chargeable as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H2089-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H2089-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall hold the National, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H2089-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, firm, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H2089-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use of possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H2089-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Wherever in this permit the term \"grantee\" is used, it shall be held and understood to mean L. S. Sarmiento & Co., Inc., its representatives, successors or assigns, unless the context indicates otherwise."}},{"id":"PH-H2089-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This temporary permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H2089-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting L. S. Sarmiento &amp; Co., Inc. a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2090"] = {"id":"PH-H2090","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2357_1959.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"授权 Joseph de Castro 将第 2044 号共和国法授予其的特许权转让给 Oceanic 无线网络公司并作相应修正","en":"An Act Authorizing the Transfer by Joseph de Castro to the Oceanic Wireless Network, Incorporated, of the Franchise Granted Him by Republic Act Numbered Two Thousand Forty-Four and Introducing Amendments Thereto","orig":"An Act Authorizing the Transfer by Joseph de Castro to the Oceanic Wireless Network, Incorporated, of the Franchise Granted Him by Republic Act Numbered Two Thousand Forty-Four and Introducing Amendments Thereto"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 2357","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2357_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2090-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The transfer of the franchise granted to Joseph de Castro by Republic Act Numbered Two thousand forty-four in favor of the Oceanic Wireless Network, Incorporated, together with all the rights and privileges appurtenant thereto, including those radio stations already established and operating under said Act, and any channel and/or frequency assignments and permits that may have been granted to the former, is hereby authorized and approved, subject to all the limitations and conditions specified in Republic Act Numbered Two thousand forty-four and other relevant laws and the provisions of the Constitution."}},{"id":"PH-H2090-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one of Republic Act Numbered Two thousand forty-four is amended to read as follows:"}},{"id":"PH-H2090-A1-d2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Oceanic Wireless Network, Incorporated, a Filipino corporation duly organized and existing under the laws of the Philippines, hereinafter referred to as the \"grantee\" a franchise to construct, install, maintain and operate, in Iloilo, Cebu and such other places in the Philippines not at present adequately served by radiotelegraph and/or radiotelephone systems, subject to the approval of the Secretary of Public Works and Communications, or any licensing authority, commercial radiotelegraph and/or radiotelephone communication stations, with corresponding relay stations, in the interisland, maritime, aeronautical and international public services, and stations in the broadcasting, television, radiophoto and facsimile services both national and/or international; to provide radio communication services and equipment to private firms, companies and corporations within their respective internal framework, and/or to communicate from within with grantee’s station or stations in the network, public fixed land based and land mobile stations.\""},"dupIndex":2},{"id":"PH-H2090-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Two new sections after section nine of the same Act are added to read as follows:\nSection 9-A . (a) The grantee shall be liable to pay the same taxes on its real estate, buildings, and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n\"(b) The grantee shall further pay to the Treasurer of the Philippines each year, within ten days after the audit and approval of the accounts as prescribed in this Act, one and one-half per centum of all gross receipts from the business transacted in the Philippines under this franchise by the grantee.\nSection 9-B . (a) This franchise shall not take effect nor shall any powers thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies or wave lengths to be used, and issued to the grantee a license for such use.\n\"(b) The Secretary of Public Works and Communications, on reasonable notice to the grantee may at any time change or cancel, or modify, in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such actions (1) whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications, or stifle competition, or to obtain a monopoly in electrical communications, or o secure unreasonable rates for communications, or to violate otherwise the laws or public policy of the Philippine Republic;\n\"(2) Whenever in his judgment the public interests of the Republic of the Philippines require that such frequencies or wave lengths should be used for other purposes that those of the grantee, either by the government of the Philippines or by other individuals or corporations licensed by it; and \"(3) Whenever in his judgment, for any reason, the public interests of the Philippines so require.\""}},{"id":"PH-H2090-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All other sections in Republic Act Numbered Two thousand forty-four not amended by this Act continue to remain current and in full force."}},{"id":"PH-H2090-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Transfer by Joseph de Castro to the Oceanic Wireless Network, Incorporated, of the Franchise Granted Him by Republic Act Numbered Two Thousand Forty-Four and Introducing Amendments Thereto","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2091"] = {"id":"PH-H2091","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2358_1959.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 San Jose Oil Company, Inc. 在菲律宾境内建设、维护和运营私人固定点对点、海岸与基站无线电台的临时许可的法案","en":"An Act Granting to the San Jose Oil Company, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Private Coastal and Private Based Stations for the Transmission and Reception of Radio Communications Within the Philippines","orig":"An Act Granting to the San Jose Oil Company, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Private Coastal and Private Based Stations for the Transmission and Reception of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2358","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2358_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2091-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the San Jose Oil Company, Inc., its successors or assigns, a temporary permit to construct, maintain and operate in the Philippines, at such places as the said company may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point, private coastal and private based radio stations for the transmission and reception of wireless communications on radiotelegraphy and radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H2091-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the grantee shall start the operation of said stations within one and a half years from the date of approval of this Act."}},{"id":"PH-H2091-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain and operate private fixed point-to-point, private coastal and private based stations in such places within the Philippines as the interest of the company and of its trade and business may justify."}},{"id":"PH-H2091-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H2091-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder, but the grantee, its successors or assigns, may use the international distress frequency whenever necessary."}},{"id":"PH-H2091-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H2091-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H2091-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred or assigned, shall be subject to all the conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H2091-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H2091-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity of disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government, upon payment of just compensation."}},{"id":"PH-H2091-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H2091-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to the San Jose Oil Company, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Private Coastal and Private Based Stations for the Transmission and Reception of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2092"] = {"id":"PH-H2092","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2359_1959.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Pablo Samonte 在布拉干省 Polo 市镇建设、运营和维护制冰厂并在该地销售冰的特许权法案","en":"An Act Granting Pablo Samonte a Franchise to Construct, Operate and Maintain an Ice Plant in the Municipality of Polo, Province of Bulacan, and to Sell Ice Therein","orig":"An Act Granting Pablo Samonte a Franchise to Construct, Operate and Maintain an Ice Plant in the Municipality of Polo, Province of Bulacan, and to Sell Ice Therein"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2359","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2359_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2092-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is granted to Pablo Samonte, hereinafter referred to as the grantee, a franchise to construct, operate and maintain an ice plant in the Municipality of Polo, Province of Bulacan, for the purpose of manufacturing and distributing ice therein and to charge and collect schedule of prices and rates for the ice so furnished, which schedule of prices and rates shall at all times be subject to regulation by the Public Service Commission."}},{"id":"PH-H2092-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of his plant, said limit to be determined by the Public Service Commission."}},{"id":"PH-H2092-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or alter any of its apparatus and appurtenances at grantee’s expense."}},{"id":"PH-H2092-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the manufacture and distribution of ice in the Municipality of Polo, Province of Bulacan, within one year from the approval of this Act, unless prevented by an act of God or force majeure martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee’s control, this franchise shall become null and void."}},{"id":"PH-H2092-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty-six as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H2092-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H2092-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H2092-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Pablo Samonte a Franchise to Construct, Operate and Maintain an Ice Plant in the Municipality of Polo, Province of Bulacan, and to Sell Ice Therein","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2093"] = {"id":"PH-H2093","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2360_1959.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"修订第 4271 号法（经修正）若干条款的法案","en":"An Act to Amend Certain Sections of Act Numbered Forty-Two Hundred and Seventy-One, as Amended","orig":"An Act to Amend Certain Sections of Act Numbered Forty-Two Hundred and Seventy-One, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2360","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2360_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 14 条，缺 3）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2093-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Act Numbered Forty-two hundred and seventy-one is hereby amended to read as follows:\n\" Sec . 1 . There is hereby granted to the Philippine Air Lines, Incorporated, hereinafter referred to as the grantee, a franchise to establish, operate and maintain transport services for the carriage of passengers, mail, and property by air and between any and all points and places throughout the Philippines, and in and between the Philippines and other countries.\""}},{"id":"PH-H2093-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two of the same Act is hereby amended to read as follows:\n\" Sec . 2 . Excepting cases of force majeure and whenever weather conditions permit, the grantee shall maintain scheduled or non-scheduled air transport services in and between any and all points and places throughout the Philippines as well as between the Philippines and other countries at such frequencies as traffic needs may require.\"\nSection 3 . Section three of the same Act is amended to read as follows:\n\" Sec . 3 . The grantee shall fix just, reasonable and uniform rates for the transportation of passengers and freight, subject to the regulations and approval of the Civil Aeronautics Board or such other regulatory agency as the Government may designate for this purpose. Any order of the Civil Aeronautics Board made under this section shall be subject to review by the courts.\n\"All aircrafts used by the grantee and the flight crew members operating such aircraft shall be licensed by the Government of the Philippines and, together with its accessories and equipment, shall at all times be in airworthy condition; it shall be equipped with radio communication, safety and other equipment and shall be operated and maintained in accordance with the regulations and technical requirements of the Civil Aeronautics Administration of such other regulatory body as the Government may prescribe for this purpose.\n\"The grantee’s equipment and the operation of such equipment shall at all times be subject to inspection and regulation by the Civil Aeronautics Administration whose decisions on technical matters shall be binding until revoked or annulled by the Department Head under whose control this office falls or by the courts for excess, or abuse of jurisdiction.\n\"The grantee shall comply with the provisions of Republic Act Numbered Seven hundred and seventy-six, and the regulations promulgated there under from time to time.\""}},{"id":"PH-H2093-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section six of the same Act is amended to read as follows:\nSec. 6 . The grantee is authorized to enter into transportation contacts with the Philippine Government, including the carrying of mail, upon terms and conditions to be mutually agreed upon. The grantee shall give preferential consideration to contracts with the Philippine Government.\""}},{"id":"PH-H2093-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section twelve of the same Act is hereby amended to read as follows:\nSec. 12 . The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the operation of the service under the franchise hereby granted.\""}},{"id":"PH-H2093-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section thirteen of the same Act is amended to read as follows:\n\" Sec . 13 . In consideration of the franchise and rights hereby granted, the grantee shall pay to the National Government during the life of this franchise a tax of two percent of the gross revenue or gross earning derived by the grantee from its operation under this franchise. Such tax shall be due and payable quarterly and shall be in lieu or all taxes of any kind, nature or description, levied, established or collected by any municipal, provincial or National authority: Provided, That if, after the audit of the accounts of the grantee by the Commissioner of Internal Revenue, a deficiency tax is shown to be due, the deficiency tax shall be payable within ten days from the receipt of the assessment. The grantee shall pay the tax on its real property in conformity with existing law.\""}},{"id":"PH-H2093-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section fourteen of the same Act is amended to read as follows:\nSec. 14 . The grantee shall keep an account of the gross receipts, revenues or earnings of the business transacted by it and shall furnish to the Commissioner of Internal Revenue a report of such gross receipts, revenues or earnings quarterly, during the month next following the close of the quarter. For the purpose of verification of gross receipts, revenues or earnings and for assessment of the franchise tax due on such gross receipts, revenues or earnings as rendered to the Commissioner of Internal Revenue, all the books and accounts of the grantee shall be kept in the Philippines, and shall be subject to inspection by the Commissioner of Internal Revenue or his authorized representatives. The audit and approval of such accounts by the Commissioner of Internal Revenue shall be final and conclusive as to the determination of the amount of said gross receipts, revenues or earnings, except that the grantee shall have the right to appeal to the courts of the Republic of the Philippines in the manner provided for by the laws of the Republic of the Philippines.\n\"the words ‘gross receipts’, ‘revenues’ and ‘earnings’ are herein defined as the total receipts obtained from transportation services or revenues derived from other services or earnings realized from the disposition of equipment by the grantee through its operation under this franchise.\""}},{"id":"PH-H2093-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section seventeen of the same Act is amended to read as follows:\nSec. 17 . This franchise is granted with the understanding that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires.\""}},{"id":"PH-H2093-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section eighteen of the same Act is amended to read as follows:\nSec. 18 . The term of this franchise shall be fifty years from the date of the acceptance of this Act by the grantee.\""}},{"id":"PH-H2093-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section twenty of the same Act is repealed."}},{"id":"PH-H2093-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Wherever the phrase \"Secretary of Public Works and Communications\" appears in sections nineteen and twenty-two of Act Numbered Forty-two hundred and seventy-one, as amended, the same shall read \"Secretary of Commerce and Industry.\""}},{"id":"PH-H2093-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Wherever the phrase \"Philippine Legislature\" appears in Act Numbered Forty-two hundred and seventy-one, the same shall read \"Congress of the Philippines.\""}},{"id":"PH-H2093-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The title of Act Numbered Forty-two hundred and seventy-one is amended to read as follows:\n\"An Act granting a franchise to the Philippine Air Lines, Incorporated, to establish, operate and maintain an air transport service in the Philippines and between the Philippines and other countries.\""}},{"id":"PH-H2093-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of Act Numbered Forty-Two Hundred and Seventy-One, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2094"] = {"id":"PH-H2094","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2361_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将若干特别或周转基金在若干条件下的现金结余归还国家政府一般基金的法案","en":"An Act Reverting to the General Funds of the National Government the Cash Balances of Certain Special or Revolving Funds Under Certain Conditions","orig":"An Act Reverting to the General Funds of the National Government the Cash Balances of Certain Special or Revolving Funds Under Certain Conditions"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2361","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2361_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2094-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the whole or any such portion of any outstanding cash balance of any special or revolving fund upon certification by the head of the office administering the said fund and attestation by the Auditor General to the effect that the purpose or purposes for which the said fund was created had been fulfilled or abandoned or that the said amount of cash balance or any portion thereof is no longer needed without adversely affecting the purpose or purposes for which the said funds was created had been fulfilled, is hereby transferred to the general funds of the national government."}},{"id":"PH-H2094-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reverting to the General Funds of the National Government the Cash Balances of Certain Special or Revolving Funds Under Certain Conditions","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2095"] = {"id":"PH-H2095","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2362_1959.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act to Amend Section One Hundred and Ninety of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code","orig":"An Act to Amend Section One Hundred and Ninety of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2362","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2362_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2095-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections twenty-one hundred and seventy, twenty-one hundred and seventy-one, and twenty-one hundred and eighty-four of the Revised Administrative Code, as amended, are further amended to read as follows:\nSec. 2170 . Classification of municipalities—Number of councilors. -Municipalities are divided into seven classes, according to their income, as follows:\n\"(a) First class: The municipalities that have obtained an average total revenue of three hundred thousand pesos or more per annum during the last four fiscal years, and shall have eight councilors;\n\"(b) Second class: The municipalities that have obtained an average total revenue of two hundred thousand pesos or more per annum, but less than three hundred thousand pesos, during the last four fiscal years, and shall have eight councilors;\n\"(c) Third class: The municipalities that have obtained an average total revenue of one hundred thousand pesos or more per annum, but less than two hundred thousand pesos, during the last four fiscal years, and shall have eight councilors;\n\"(d) Fourth class: The municipalities that have obtained an average total revenue of fifty thousand pesos or more per annum but less than one hundred thousand pesos, during the last four fiscal years, and shall have eight councilors;\n\"(e) Fifth class: The municipalities that have obtained an average total revenue of thirty thousand pesos or more per annum, but less than fifty thousand pesos, during the last four fiscal years, and shall have eight councilors;\n\"(f) Sixth class: The municipalities that have obtained an average total revenue of fifteen thousand pesos or more per annum, but less than thirty thousand pesos, during the last four fiscal years, and shall have six councilors:\n\"(g) Seventh class: The municipalities that have obtained an average total revenue of less than fifteen thousand pesos per annum during the last four fiscal years, and shall have six councilors: Provided, That municipalities with an average total revenue of less than five thousand pesos per annum during the same fiscal period shall have only four councilors:\n\" Provided, further, That the councilors elected at the last general election in each municipality shall continue to hold office during the term for which they were elected, and the reduction or increase of the number of councilors in accordance with the classification of municipalities prescribed in this Act shall take effect beginning with the general election of nineteen hundred and fifty-nine.\nSec. 2171 . Classification of municipalities by the Secretary of Finance. -Beginning July first, nineteen hundred and fifty-eight, and for each period of four consecutive fiscal years after said date, the Secretary of Finance shall classify all municipalities on the basis of their average annual income during the four consecutive fiscal years immediately preceding such classification in accordance with the provisions of the next preceding section as certified by the Auditor General.\nSec. 2184 . Maximum limit of salaries. -Except as otherwise specially provided herein, the annual salaries of municipal officers shall not exceed the amounts here in below fixed:\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years and average total annual revenue of one million four hundred thousand pesos or more (First-1): For the mayor, seven thousand eight hundred pesos; for the municipal treasurer, six thousand four hundred and eighty pesos; for the municipal secretary, four thousand two hundred pesos; for the chief of police, three thousand seven hundred and twenty pesos; and for the chief of municipal fire department, three thousand one hundred and twenty pesos.\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of one million pesos or more but less than one million four hundred thousand pesos (First-2): For the mayor, seven thousand five hundred pesos; for the municipal treasurer, six thousand one hundred and twenty pesos; for the municipal secretary, three thousand nine hundred and sixty pesos; for the chief of police, three thousand six hundred pesos; and for the chief of municipal fire department, three thousand pesos.\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of seven hundred thousand pesos or more but less than one million pesos (First-3): For the mayor, seven thousand two hundred pesos; for the municipal treasurer, five thousand seven hundred and sixty pesos; for the municipal secretary, three thousand seven hundred and eighty pesos; for the chief of police, three thousand four hundred and eighty pesos; and for the chief of municipal fire department, two thousand eight hundred and eighty pesos.\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years and average total annual revenue of five hundred thousand pesos or more but less than seven hundred thousand pesos (First-4): For the mayor, six thousand six hundred pesos; for the municipal treasurer, five thousand four hundred pesos; for the municipal secretary, three thousand six hundred pesos; for the chief of police, three thousand three hundred pesos; and for the chief of municipal fire department, two thousand seven hundred and sixty pesos.\n\"In other municipalities of the first class with an average total annual revenue of three hundred thousand pesos or more but less than five hundred thousand pesos (First-5): For the mayor, six thousand pesos; for the municipal treasurer, five thousand and forty pesos; for the municipal secretary, three thousand three hundred and sixty pesos; for the chief of police, three thousand pesos; and for the chief of municipal fire department, two thousand five hundred and eighty pesos.\n\"In municipalities of the second class: For the mayor, five thousand four hundred pesos; for the municipal treasurer, four thousand six hundred and eighty pesos; for the municipal secretary, three thousand pesos; for the chief of police, two thousand seven hundred pesos; and for the chief of municipal fire department, two thousand four hundred pesos.\n\"In municipalities of the third class: For the mayor, four thousand eight hundred pesos; for the municipal treasurer, four thousand three hundred and twenty pesos; for the municipal secretary, two thousand seven hundred pesos; for the chief of police, two thousand four hundred pesos; and for the chief of municipal fire department, two thousand or one hundred and sixty pesos.\n\"In municipalities of the fourth class: For the mayor, four thousand two hundred pesos; for the municipal treasurer, three thousand seven hundred and eighty pesos; for the municipal secretary, two thousand four hundred pesos; for the chief of police, two thousand two hundred and eighty pesos and for the chief of municipal fire department, two thousand and forty pesos.\n\"In municipalities of the fifth class: For the mayor, three thousand six hundred pesos; for the municipal treasurer, three thousand two hundred and forty pesos; for the municipal secretary, two thousand one hundred and sixty pesos; for the chief of police, two thousand and forty pesos; and for the chief of municipal fire department, one thousand eight hundred pesos.\n\"In municipalities of the sixth class: For the mayor, two thousand seven hundred and sixty pesos; for the municipal treasurer, two thousand four hundred pesos; for the municipal secretary, one thousand five hundred and sixty pesos; and for the chief of police, one thousand six hundred and eighty pesos.\n\"In municipalities of the seventh class: For the mayor, two thousand one hundred and sixty pesos; for the municipal treasurer one thousand nine hundred and twenty pesos; for the municipal secretary, one thousand four hundred and forty pesos; and for the chief of police, one thousand four hundred and forty pesos.\n\"Two-third of the salary of the municipal treasurer shall be paid out of municipal funds, in his capacity as such, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer: Provided, That the provincial board concerned may, in its discretion, authorize as salary of the municipal treasurer in his capacity as deputy of the provincial treasurer an amount more than the maximum rate fixed herein as payable from provincial funds, provided the corresponding maximum salary rate hereinabove fixed is not exceeded.\n\"With the approval of the Secretary of Finance, the annual salaries of municipal officers of a municipality which is the capital of a province or a subprovince may be fixed at rates higher than those authorized for the class to which the municipality belongs: Provided, That the salaries so fixed shall not exceed the maximum rates authorized for the corresponding officers in the next higher scale of salaries herein established: Provided, further, That in case no higher scale is provided herein, said salaries of officers of provincial and subprovincial capitals may, with the approval of the Secretary of Finance, be increased by not more than three hundred and sixty pesos per annum.\""}},{"id":"PH-H2095-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Paragraph one of section twenty-one hundred and eighty-seven of the Revised Administrative Code, as amended by Republic Act Numbered Nineteen hundred and forty-three, is further amended to read as follows:\n\" Sec. 2187 . Compensation of vice-mayor and councilors—Full pay for sick mayor. -The municipal council may grant to the vice-mayor and each councilor a per diem not to exceed twenty pesos in municipalities of the first class; eighteen pesos in municipalities of the second class; fifteen pesos in municipalities of the third class; twelve pesos in municipalities of the fourth class; ten pesos in municipalities of the fifth class; eight pesos in municipalities of the sixth class; and six pesos in the seventh class municipalities, for each day of regular or special session of the council actually attended by them: Provided, However, That no per diem may be granted for more than four special sessions a month. When, by reason of absence, suspension, or other disability, the mayor ceases to discharge the duties of his office, the vice-mayor or councilor acting as mayor shall receive compensation equivalent to the salary of the mayor during the period of such service.\""}},{"id":"PH-H2095-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section twenty-two hundred and seventy-seven of the Revised Administrative Code is hereby amended to read as follows:\nSec. 2277-B . Salaries of members of municipal fire department. -The salaries of the chief and other members of the municipal fire department shall be fixed by the municipal council.\""}},{"id":"PH-H2095-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Sections twenty-two hundred and ninety-one (A) and twenty-two hundred and ninety-nine of the Revised Administrative Code, as amended, are further amended to read as follows:\n\" Sec. 2291 (A). Municipal permanent public improvement fund. -There shall be a special fund in the treasury of each municipality which shall be known as permanent public improvement fund. To this fund shall accrue the appropriations from time to time made by the municipal council and twelve per centum of the municipal general fund in first, second, and third class municipalities, ten per centum in fourth and fifth class municipalities, and eight per centum in sixth and seventh class municipalities, as defined in the next preceding section. This fund shall be available exclusively for the construction and maintenance of all public improvements: Provided, That if the municipal council should require this fund for other peremptory needs of the municipality, it may use it for the same, subject to the approval of the provincial board.\nSec. 2 2 99 . General limitation upon amount expendable for salaries and wages. -Except as hereinbelow provided, there shall not be expended during any fiscal year for salaries and wages of municipal officials and employees of every description, excluding those employed on public works, in municipalities of the first class more than fifty-five per centum, in municipalities of the second class more than sixty per centum, in municipalities of the third class more than sixty-five per centum, in municipalities of the fourth class more than seventy per centum, in municipalities of the fifth class more than seventy-five per centum, in municipalities of the sixth class more than eighty per centum, of the annual revenues accruing to the municipal general funds during said fiscal year, exclusive of all balances carried forward from preceding years, and any and all appropriations, loans, or gifts made from national, provincial, or private funds.\n\"With the approval of the Secretary of Finance a municipality may, for justifiable cause, exceed the foregoing percentages under such limitations as may be prescribed by the said Secretary.\""}},{"id":"PH-H2095-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Upon the first classification of municipalities provided in this Act, the provisions of existing laws, orders, rules and/or regulations referring to the first class-A municipalities shall apply to the first class or the second class municipalities, as the case may be, and those referring to the first class-B, first class, second class, third class, and the fourth and fifth class municipalities shall apply to the third class, fourth class, fifth class, sixth class, and the seventh class municipalities, respectively, as defined in this Act: Provided, That the term \"first class municipalities,\" or \"municipalities of the first class,\" or \"municipalities belonging to the first class group,\" or other similar term, whenever used in any provision of existing law, order, rule or regulation not expressly amended or modified by this Act, shall, upon the initial classification of municipalities herein provided, apply to the fourth, third, second and first class municipalities as defined in section one hereof: Provided, further, That municipalities with an average total annual revenue of less than five thousand pesos shall not be subject to the financial contribution provided in section two of Republic Act Numbered Nineteen hundred and thirty-nine."}},{"id":"PH-H2095-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The municipal officers mentioned in this Act shall be entitled to receive the full amount of the appropriations for their salaries which may be provided and approved in the corresponding provincial and municipal budgets in accordance with the provisions of section one hereof, any provision of existing laws, rules and regulations to the contrary notwithstanding: Provided, That the maximum rate of compensation authorized for the civil service eligibility, where this is required, of the officer concerned is not exceeded."}},{"id":"PH-H2095-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Paragraphs two, three, four, five, six, seven, eight, nine, and ten of section twenty-two hundred and seventy-three of the Revised Administrative Code, as amended, section three of Republic Act Numbered Thirteen hundred and forty-six, and all other Acts or parts thereof which are inconsistent with any provision of this Act are hereby repealed and/or modified accordingly."}},{"id":"PH-H2095-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29"};
  FT["PH-H2096"] = {"id":"PH-H2096","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2363_1959.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"进一步修订第 3992 号法（即经修正的《修订机动车法》）的法案","en":"An Act to Amend Further Act Numbered Thirty-Nine Hundred and Ninety-Two, Otherwise Known as the Revised Motor Vehicles Law, as Amended","orig":"An Act to Amend Further Act Numbered Thirty-Nine Hundred and Ninety-Two, Otherwise Known as the Revised Motor Vehicles Law, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2363","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2363_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2096-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph (b) of section five of Act Numbered Thirty-nine hundred ninety-two, otherwise known as the Revised Motor Vehicles Law, as amended, is further amended, to read as follows:\n\"(b) Any registration of motor vehicles not renewed on or before the date fixed for different classifications as provided hereunder shall become delinquent and invalid:\n1. For hire motor vehicles—on or before the last working day of February\n2. Privately owned motor vehicles—on or before the last working day of March\n3. All other motor vehicles—on or before the last working day of April except when the plates of such motor vehicles are returned to the Motor Vehicles Office in Manila, or to the Office of the Motor Vehicle Registrar in the provincial or city agencies of the Motor Vehicles Office on or before the last working day of December of the year of issue.\""}},{"id":"PH-H2096-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Paragraphs (b) and (c) of section eight of the same Act, as amended, are further amended to read as follows:\n\"(b) Private automobiles with pneumatic rubber tires, an amount based on their respective shipping weight or factory weight as indicated in the following schedule:\n1000 kilos or less ₱75.00 1001 to 1500 kilos 100.00 1501 to 2000 kilos 135.00 2001 and above 180.00 \"The factory or shipping weight of a private automobile shall be obtained from the Red Book edited by the National Market Report, Inc., of the United States of America: Provided, That in the case of automobiles with altered, changed or rebuilt bodies, the weight as obtained by actual weighing shall be considered the vehicle weight: Provided further, That the increased registration fees herein prescribed shall not apply to jeeps and jeepneys for private use or for hire and the fees thereof shall be those prescribed for them before the approval of this Act.\n\"The registered passenger capacity of passenger automobiles operated for hire or for private use shall be determined as follows:\n\"1. For each adult passenger, not less than a horizontal rectangular area, including seat and foot space, 40 cm. wide and 60 cm. long, except in the front seat which shall allow 50 cm. wide for the operator.\n\"2. For each half-passenger, not less than a horizontal rectangular area, including seat and foot space, 20 cm. wide by 60 cm. long, provided that each continuous row of seats shall not be allowed more than one-half passenger.\n\"(c) Private motor trucks, passenger buses and trailers with pneumatic rubber tires, the sum of five pesos per hundred kilograms of maximum allowable gross weight or fraction thereof.\""}},{"id":"PH-H2096-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section seventeen of the same Act, as amended, is further amended to read as follows:\n\"Sec. 17. Number plate, preparation and issuance of. -(a) The Chief of the Motor Vehicles Office shall cause number plates to be prepared and issued to owners of motor vehicles and trailers registered under this Act, charging a fee of one peso for each complete plate including the numerals indicating the year of registry: Provided, However, That in case no number plates are available, the Chief of the Motor Vehicles Office or his deputies may issue, without charge, a written permit temporarily authorizing the operation of any motor vehicles with other means of identification: Provided, further, That all motor vehicles exempted from payment of registration fees, motor vehicles for hire, and privately owned motor vehicles, shall bear plates so designed and painted with different colors to distinguish one class from the other: Provided, still further, That the plates of motor vehicles exempted from payment of registration fees shall be permanently assigned to such motor vehicles during their entire lifetime while exempted from payment of fees: And Provided, finally, That the owner thereof shall return such plate to the Chief of the Motor Vehicles Office within a period of seven working days after such owner has lost his exemption privilege or has transferred the vehicle to a non-exempt owner.\n\"(b) In case the design of the number plate is such that the numerals indicating the year of registry are in a detachable tag, the Chief, Motor Vehicles Office or his deputies may, in their discretion, issue the said tag only, for subsequent re-registration, charging a fee of fifty centavos for each tag issued.\""}},{"id":"PH-H2096-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section twenty-four of the same Act, as amended, is further amended to read as follows:\n\"Sec. 24. Driver’s license, fees, examination. -Every person who desires personally to operate any motor vehicle shall make application to the Chief, Motor Vehicles Office or his deputies for a license to drive motor vehicles: Provided, However, That no person shall be issued a professional chauffeur’s license who is suffering from highly contagious diseases, such as, advanced tuberculosis, gonorrhea, syphilis, and the like.\n\"Each such application except in the case of enlisted men operating Government owned vehicles shall be accompanied by a fee of five pesos, and shall contain such information respecting the applicant and his ability to operate motor vehicles, as may be required by the Chief, Motor Vehicles Office.\n\"The Chief, Motor Vehicles Office or his deputies shall also ascertain that the applicant’s sight and hearing are normal, and may, in their discretion, require a certificate to that effect, signed by a reputable physician.\n\"An examination or demonstration to show any applicant’s ability to operate motor vehicles may also be required in the discretion of the Chief, Motor Vehicles Office or his deputies.\""}},{"id":"PH-H2096-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section thirty-one, article one, Chapter Three of the same Act, as amended, is further amended to read as follows:\n\"Sec. 31. Renewal of license. -Any license not renewed every year on or before the last working day of the month when the applicant was born shall become delinquent and invalid.\n\"The fee for renewal of delinquent license shall be five pesos, in addition to the basic fee as hereinabove prescribed.\n\"Every applicant for renewal of license to operate any motor vehicle shall present to the Chief, Motor Vehicles Office either in person or by mail or messenger the license issued to the applicant for the previous year, together with the proper fee of five pesos and, in the case of professional chauffeurs, three copies of a readily recognized photograph of the applicant which photograph shall have been taken not exceeding three years prior to the date of appreciation for renewal.\n\" Lost license. -In case the license for the previous year has been lost or cannot be produced, the applicant shall obtain a duplicate on accord with section ten of this Act, on penalty of refusal, by the Chief, Motor Vehicles Office or his deputies to renew the license: Provided, However, That the Chief, Motor Vehicles Office or his deputies may, in their discretion, accept in lieu of the previous year’s license, the duly signed and sworn statement of an operator to the effect that he has not operated any motor vehicle in the Philippines during the year or years for which no license was issued in his name.\n\"The Chief, Motor Vehicles Office and his deputies are hereby authorized to administer the oath in connection with such affidavit.\""}},{"id":"PH-H2096-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect with respect to car license and drivers’ licenses for the calendar year nineteen hundred and sixty.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Further Act Numbered Thirty-Nine Hundred and Ninety-Two, Otherwise Known as the Revised Motor Vehicles Law, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2097"] = {"id":"PH-H2097","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2365_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"使甲米地省学校分区督学兼任甲米地市学校督学，为此修订第547号联邦法（即《甲米地市宪章》）第84条的法案","en":"An Act Making the Division Superintendent of Schools of Cavite Ex-Officio Superintendent of Schools of the City of Cavite, Amending for This Purpose Section Eighty-Four of Commonwealth Act Numbered Five Hundred Forty-Seven, Otherwise Known as the Charter of the City of Cavite","orig":"An Act Making the Division Superintendent of Schools of Cavite Ex-Officio Superintendent of Schools of the City of Cavite, Amending for This Purpose Section Eighty-Four of Commonwealth Act Numbered Five Hundred Forty-Seven, Otherwise Known as the Charter of the City of Cavite"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2365","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2365_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2097-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eighty-four of Commonwealth Act Numbered Five hundred forty-seven, otherwise known as the Charter of the City of Cavite, is amended to read as follows:\n\"Sec. 84. The Bureau of Public Schools. -The Director of Public Schools shall exercise the same jurisdiction and powers in the city as elsewhere in the Philippines and the Division Superintendent of Schools for the Province of Cavite shall be ex officio Superintendent of Schools for the City of Cavite and as such he shall have all the powers and duties in respect to the schools of the city as are vested in division superintendents in respect to the schools of their divisions. He shall receive an additional compensation of one thousand pesos per annum which shall be paid by the city.\n\"A city school board of six members, two of whom shall be women and who shall serve without salary, shall be selected and removed in the same manner, and shall have the same powers and duties, as local school boards in municipalities.\n\"The municipal board shall have the same powers in respect to the establishment of schools as are conferred by law on municipal councils.\""}},{"id":"PH-H2097-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Making the Division Superintendent of Schools of Cavite Ex-Officio Superintendent of Schools of the City of Cavite, Amending for This Purpose Section Eighty-Four of Commonwealth Act Numbered Five Hundred Forty-Seven, Otherwise Known as the Charter of the City of Cavite","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2098"] = {"id":"PH-H2098","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2366_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第328号共和国法（即《Calbayog市宪章》）若干条款的法案","en":"An Act Amending Certain Sections of Republic Act Numbered Three Hundred Twenty-Eight, Otherwise Known as the Charter of the City of Calbayog","orig":"An Act Amending Certain Sections of Republic Act Numbered Three Hundred Twenty-Eight, Otherwise Known as the Charter of the City of Calbayog"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2366","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2366_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2098-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections seven, eight, eleven and thirteen of Republic Act Numbered Three hundred twenty-eight, otherwise known as the Charter of the City of Calbayog, are amended to read as follows:\n\"Sec. 7. The Mayor. -The Mayor shall be the chief executive of the city. He shall be elected by the qualified voters of the city during every election for provincial and municipal officials in accordance with the provisions of the Revised Election Code. No person shall be eligible for the position of mayor unless he is at least thirty years of age, a resident of the city for at least five years and a qualified voter therein.\n\"He shall receive the salary provided for in Republic Act Numbered Eight hundred forty. With the approval of the President, the Mayor may be provided, in addition to his salary, a non-commutable allowance of not exceeding two thousand pesos per annum.\n\"Sec. 8. The Vice-Mayor. -There shall be a Vice-Mayor who shall perform the duties of Mayor in the event of the sickness, absence or other temporary incapacity of the Mayor, or in the event of a definite vacancy in the position of Mayor, until said office is filled in accordance with law. The Vice-Mayor shall also preside over the meetings of the Municipal Board, but he shall have no right to vote except in case of tie. If, for any reason, the Vice-Mayor is temporarily incapacitated for the performance of the duties of the Mayor, or said office of the Vice-Mayor is vacant, the duties of the Mayor shall be performed by the city treasurer. The Acting Mayor shall have the same powers and duties as the Mayor.\n\"The Vice-Mayor shall perform such other duties as may be assigned to him by the Mayor or prescribed by law or ordinance. He shall be elected in the same manner as the Mayor and shall at the time of his election possess the same qualifications as the Mayor. He shall receive a salary of four thousand two hundred pesos per annum. For services as Acting Mayor the Vice-Mayor shall receive a total of the compensation equivalent to the salary of the Mayor during such period.\n\"Sec. 11. Constitution and organization of the Municipal Board; Compensation of members thereof. -The Municipal Board shall be the legislative body of the city and shall be composed of the Vice-Mayor who shall be its presiding office, and ten councilors who shall be elected during every election for provincial and municipal officials in accordance with the provisions of the Revised Election Code. The said presiding officer shall vote only in case of tie. No person shall be eligible for the position of member of the board unless he is at least twenty-five years of age, a resident of the city for at least three years and a qualified elector therein. In case of sickness, absence, suspension or other temporary disability of any member of the Board, or if necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute who shall possessed all the rights and perform all the duties of a member of the Board until the return to duty of the regular incumbent.\n\"If any member of the Municipal Board should be candidate for office in any election, he shall be disqualified to act with the Board in the discharge of the duties conferred upon it relative to election matters, and in such case the other members of the Board shall discharge said duties without his assistance, or they may choose some disinterested elector of the city to act with the Board in such matters in his stead.\n\"The members of the Municipal Board shall receive the per diem provided for in Republic Act Numbered Eight hundred forty.\n\"Sec. 13. Method of transacting business by the board— Veto— Authentication and publication of ordinances. -Unless the President orders otherwise, the board shall hold one ordinary session for the transaction of business during each week on a day which it shall fix by resolution, and such extraordinary session, not exceeding thirty during any one year, as may be called by the Mayor. It shall sit with open doors, unless otherwise ordered by an affirmative vote of seven members. It shall keep a record of its proceedings and determine its rules of procedure not herein set forth. Seven members of the Board shall constitute a quorum for the transaction of business. But a smaller number may adjourn form day to day and may compel the immediate attendance of any member absent without good cause by issuing to the police of the city an order for his arrest and production at the session under such penalties as shall have been previously prescribed by ordinance. Seven affirmative votes shall be necessary for the passage of any ordinance, or of any resolution or motion directing the payment of money or creating liability, but other measures shall prevail upon the majority votes of the members present at any meeting duly called and held. The ayes and mays shall be taken and recorded upon the passage of all ordinances, upon all resolutions or motions directing the payment of money or creating liability, and at the request of any member, upon any other resolution or motion. Each approved ordinance, resolution or motion shall be sealed with the seal of the board, signed by the presiding officer and the secretary of the board and recorded in a book for the purpose and shall, on the day following its passage, be posted by the secretary at the main entrance of the city hall, and shall take effect and be in force on and after the tenth day following its passage unless otherwise stated in said ordinance, resolution or motion or vetoed by the Mayor as hereinafter provided. A vetoed ordinance, if repassed, shall take effect ten days after the veto is over-ridden by the required votes unless otherwise stated in the ordinance or again disapproved by the Mayor within said time.\n\"Each ordinance and each resolution or motion directing the payment of money or creating liability enacted or adopted by the board shall be forwarded to the Mayor for his approval. Within ten days after the receipt of the ordinance, resolution or motion, the Mayor shall return it with his veto, his reasons therefor in writing shall accompany it. It may then be again enacted by the affirmative votes of eight members of the board, and again forwarded to the Mayor for his approval, and if within ten days after its receipts he does not again return it with his veto, it shall be deemed to be approved. If within said time he again returns it with his veto, it shall be forwarded forthwith to the President for his approval or disapproval, within shall be final. The Mayor shall have the power to veto any particular item or items of an appropriation ordinance, or of an ordinance, resolution or motion directing the payment of money or creating liability, but the veto shall not affect the item or items to which he does not object. The item or items objected to shall not take effect except in the manner heretofore provided in this section as to ordinances, resolutions and motions returned to the board with his veto, but should an item or items in an appropriation ordinance be disapproved by the Mayor, the corresponding item or items in the appropriation ordinance of the previous year shall be deemed restored unless other wise expressly directed in the veto.\""}},{"id":"PH-H2098-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first paragraph of section twenty-five of the same Act is amended to read as follows:\n\"Sec. 25. The city attorney— His powers and duties. -The city attorney shall be the chief legal adviser of the city. He shall receive the salary provided for in Republic Act Numbered Eight hundred forty. He shall be assisted in the discharge of his duties by an assistant city attorney who shall receive a salary of three thousand three hundred pesos per annum. The city attorney shall have the following powers and duties.\""}},{"id":"PH-H2098-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first paragraph of section twenty-six of the same Act is amended to read as follows:\n\"Sec. 26. The Chief of Police— His powers, duties and compensation. -There shall be a chief of police who shall have charge of the police department and who shall receive the salary provided for in Republic Act Numbered Eight hundred forty. He shall be assisted in the discharge of his duties by an assistant chief of police, who shall receive a salary of two thousand four hundred pesos per annum. The chief of police shall have the following general powers and duties:\""}},{"id":"PH-H2098-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Certain Sections of Republic Act Numbered Three Hundred Twenty-Eight, Otherwise Known as the Charter of the City of Calbayog","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2099"] = {"id":"PH-H2099","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2367_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"拨款5万比索用于1959年11月在菲律宾举行第十四届世界旅游大会，并用于购置与安装适当的会议设备、服务与用品","en":"An Act to Appropriate the Sum of Fifty Thousand Pesos for the Holding of the XIVth World Congress on Tourism in the Philippines in November, Nineteen Hundred Fifty-Nine, and for the Acquisition and Installation of Adequate Conference Equipment, Services and Supplies","orig":"An Act to Appropriate the Sum of Fifty Thousand Pesos for the Holding of the XIVth World Congress on Tourism in the Philippines in November, Nineteen Hundred Fifty-Nine, and for the Acquisition and Installation of Adequate Conference Equipment, Services and Supplies"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2367","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2367_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2099-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated the sum of fifty thousand pesos, out of any funds in the National Treasury not otherwise appropriated, to cover expenses required for the holding of the World Congress on Tourism in November, nineteen hundred fifty-nine, including the acquisition and installation of modern conference hall equipment and facilities, communication and transportation services and essential conference supplies."}},{"id":"PH-H2099-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The fund hereby appropriated shall be made immediately available upon approval of this Act and be at the disposal of the Board of Travel and Tourist Industry, which shall be responsible for its expenditure as well as for the safekeeping and any future use of the conference equipment to be acquired."}},{"id":"PH-H2099-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Appropriate the Sum of Fifty Thousand Pesos for the Holding of the XIVth World Congress on Tourism in the Philippines in November, Nineteen Hundred Fifty-Nine, and for the Acquisition and Installation of Adequate Conference Equipment, Services and Supplies","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2100"] = {"id":"PH-H2100","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2368_1959.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"修订经修正的《修订行政法典》若干条以规定市镇分类、确定市镇官员薪金上限并为其他目的法案","en":"An Act to Amend Certain Sections of the Revised Administrative Code, as Amended, so as to Provide for the Classification of Municipalities, to Fix the Maximum Limit of the Salaries of Municipal Officers, and for Other Purposes","orig":"An Act to Amend Certain Sections of the Revised Administrative Code, as Amended, so as to Provide for the Classification of Municipalities, to Fix the Maximum Limit of the Salaries of Municipal Officers, and for Other Purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 2368","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2368_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2100-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections twenty-one hundred and seventy, twenty-one hundred and seventy-one, and twenty-one hundred and eighty-four of the Revised Administrative Code, as amended, are further amended to read as follows:\n\"Sec. 2170. Classification of municipalities—Number of councilors. -Municipalities are divided into seven classes, according to their income, as follows:\n\"(a) First class: The municipalities that have obtained an average total revenue of three hundred thousand pesos or more per annum during the last four fiscal years, and shall have eight councilors;\n\"(b) Second class: The municipalities that have obtained an average total revenue of two hundred thousand pesos or more per annum, but less than three hundred thousand pesos, during the last four fiscal years, and shall have eight councilors;\n\"(c) Third class: The municipalities that have obtained an average total revenue of one hundred thousand pesos or more per annum, but less than two hundred thousand pesos, during the last four fiscal years, and shall have eight councilors;\n\"(d) Fourth class: The municipalities that have obtained an average total revenue of fifty thousand pesos or more per annum but less than one hundred thousand pesos, during the last four fiscal years, and shall have eight councilors;\n\"(e) Fifth class: The municipalities that have obtained an average total revenue of thirty thousand pesos or more per annum, but less than fifty thousand pesos, during the last four fiscal years, and shall have eight councilors;\n\"(f) Sixth class: The municipalities that have obtained an average total revenue of fifteen thousand pesos or more per annum, but less than thirty thousand pesos, during the last four fiscal years, and shall have six councilors:\n\"(g) Seventh class: The municipalities that have obtained an average total revenue of less than fifteen thousand pesos per annum during the last four fiscal years, and shall have six councilors: Provided, That municipalities with an average total revenue of less than five thousand pesos per annum during the same fiscal period shall have only four councilors:\n\" Provided, further, That the councilors elected at the last general election in each municipality shall continue to hold office during the term for which they were elected, and the reduction or increase of the number of councilors in accordance with the classification of municipalities prescribed in this Act shall take effect beginning with the general election of nineteen hundred and fifty-nine.\n\"Sec. 2171. Classification of municipalities by the Secretary of Finance. -Beginning July first, nineteen hundred and fifty-eight, and for each period of four consecutive fiscal years after said date, the Secretary of Finance shall classify all municipalities on the basis of their average annual income during the four consecutive fiscal years immediately preceding such classification in accordance with the provisions of the next preceding section as certified by the Auditor General.\n\"Sec. 2184. Maximum limit of salaries. -Except as otherwise specially provided herein, the annual salaries of municipal officers shall not exceed the amounts hereinbelow fixed:\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years and average total annual revenue of one million four hundred thousand pesos or more (First-1): For the mayor, seven thousand eight hundred pesos; for the municipal treasurer, six thousand four hundred and eighty pesos; for the municipal secretary, four thousand two hundred pesos; for the chief of police, three thousand seven hundred and twenty pesos; and for the chief of municipal fire department, three thousand one hundred and twenty pesos.\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of one million pesos or more but less than one million four hundred thousand pesos (First-2): For the mayor, seven thousand five hundred pesos; for the municipal treasurer, six thousand one hundred and twenty pesos; for the municipal secretary, three thousand nine hundred and sixty pesos; for the chief of police, three thousand six hundred pesos; and for the chief of municipal fire department, three thousand pesos.\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of seven hundred thousand pesos or more but less than one million pesos (First-3): For the mayor, seven thousand two hundred pesos; for the municipal treasurer, five thousand seven hundred and sixty pesos; for the municipal secretary, three thousand seven hundred and eighty pesos; for the chief of police, three thousand four hundred and eighty pesos; and for the chief of municipal fire department, two thousand eight hundred and eighty pesos.\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years and average total annual revenue of five hundred thousand pesos or more but less than seven hundred thousand pesos (First-4): For the mayor, six thousand six hundred pesos; for the municipal treasurer, five thousand four hundred pesos; for the municipal secretary, three thousand six hundred pesos; for the chief of police, three thousand three hundred pesos; and for the chief of municipal fire department, two thousand seven hundred and sixty pesos.\n\"In other municipalities of the first class with an average total annual revenue of three hundred thousand pesos or more but less than five hundred thousand pesos (First-5): For the mayor, six thousand pesos; for the municipal treasurer, five thousand and forty pesos; for the municipal secretary, three thousand three hundred and sixty pesos; for the chief of police, three thousand pesos; and for the chief of municipal fire department, two thousand five hundred and eighty pesos.\n\"In municipalities of the second class: For the mayor, five thousand four hundred pesos; for the municipal treasurer, four thousand six hundred and eighty pesos; for the municipal secretary, three thousand pesos; for the chief of police, two thousand seven hundred pesos; and for the chief of municipal fire department, two thousand four hundred pesos.\n\"In municipalities of the third class: For the mayor, four thousand eight hundred pesos; for the municipal treasurer, four thousand three hundred and twenty pesos; for the municipal secretary, two thousand seven hundred pesos; for the chief of police, two thousand four hundred pesos; and for the chief of municipal fire department, two thousand or one hundred and sixty pesos.\n\"In municipalities of the fourth class: For the mayor, four thousand two hundred pesos; for the municipal treasurer, three thousand seven hundred and eighty pesos; for the municipal secretary, two thousand four hundred pesos; for the chief of police, two thousand two hundred and eighty pesos and for the chief of municipal fire department, two thousand and forty pesos.\n\"In municipalities of the fifth class: For the mayor, three thousand six hundred pesos; for the municipal treasurer, three thousand two hundred and forty pesos; for the municipal secretary, two thousand one hundred and sixty pesos; for the chief of police, two thousand and forty pesos; and for the chief of municipal fire department, one thousand eight hundred pesos.\n\"In municipalities of the sixth class: For the mayor, two thousand seven hundred and sixty pesos; for the municipal treasurer, two thousand four hundred pesos; for the municipal secretary, one thousand five hundred and sixty pesos; and for the chief of police, one thousand six hundred and eighty pesos.\n\"In municipalities of the seventh class: For the mayor, two thousand one hundred and sixty pesos; for the municipal treasurer one thousand nine hundred and twenty pesos; for the municipal secretary, one thousand four hundred and forty pesos; and for the chief of police, one thousand four hundred and forty pesos.\n\"Two-third of the salary of the municipal treasurer shall be paid out of municipal funds, in his capacity as such, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer: Provided, That the provincial board concerned may, in its discretion, authorize as salary of the municipal treasurer in his capacity as deputy of the provincial treasurer an amount more than the maximum rate fixed herein as payable from provincial funds, provided the corresponding maximum salary rate hereinabove fixed is not exceeded.\n\"With the approval of the Secretary of Finance, the annual salaries of municipal officers of a municipality which is the capital of a province or a subprovince may be fixed at rates higher than those authorized for the class to which the municipality belongs: Provided, That the salaries so fixed shall not exceed the maximum rates authorized for the corresponding officers in the next higher scale of salaries herein established: Provided, further, That in case no higher scale is provided herein, said salaries of officers of provincial and subprovincial capitals may, with the approval of the Secretary of Finance, be increased by not more than three hundred and sixty pesos per annum.\""}},{"id":"PH-H2100-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Paragraph one of section twenty-one hundred and eighty-seven of the Revised Administrative Code, as amended by Republic Act Numbered Nineteen hundred and forty-three, is further amended to read as follows:\n\"Sec. 2187. Compensation of vice-mayor and councilors—Full pay for sick mayor. -The municipal council may grant to the vice-mayor and each councilor a per diem not to exceed twenty pesos in municipalities of the first class; eighteen pesos in municipalities of the second class; fifteen pesos in municipalities of the third class; twelve pesos in municipalities of the fourth class; ten pesos in municipalities of the fifth class; eight pesos in municipalities of the sixth class; and six pesos in the seventh class municipalities, for each day of regular or special session of the council actually attended by them: Provided, However, That no per diem may be granted for more than four special sessions a month. When, by reason of absence, suspension, or other disability, the mayor ceases to discharge the duties of his office, the vice-mayor or councilor acting as mayor shall receive compensation equivalent to the salary of the mayor during the period of such service.\""}},{"id":"PH-H2100-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section twenty-two hundred and seventy-seven of the Revised Administrative Code is hereby amended to read as follows:\n\"Sec. 2277-B. Salaries of members of municipal fire department. -The salaries of the chief and other members of the municipal fire department shall be fixed by the municipal council.\""}},{"id":"PH-H2100-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Sections twenty-two hundred and ninety-one (A) and twenty-two hundred and ninety-nine of the Revised Administrative Code, as amended, are further amended to read as follows:\n\"Sec. 2291 (A). Municipal permanent public improvement fund. -There shall be a special fund in the treasury of each municipality which shall be known as permanent public improvement fund. To this fund shall accrue the appropriations from time to time made by the municipal council and twelve per centum of the municipal general fund in first, second, and third class municipalities, ten per centum in fourth and fifth class municipalities, and eight per centum in sixth and seventh class municipalities, as defined in the next preceding section. This fund shall be available exclusively for the construction and maintenance of all public improvements: Provided, That if the municipal council should require this fund for other peremptory needs of the municipality, it may use it for the same, subject to the approval of the provincial board.\n\"Sec. 2299. General limitation upon amount expendable for salaries and wages.— Except as hereinbelow provided, there shall not be expended during any fiscal year for salaries and wages of municipal officials and employees of every description, excluding those employed on public works, in municipalities of the first class more than fifty-five per centum, in municipalities of the second class more than sixty per centum, in municipalities of the third class more than sixty-five per centum, in municipalities of the fourth class more than seventy per centum, in municipalities of the fifth class more than seventy-five per centum, in municipalities of the sixth class more than eighty per centum, of the annual revenues accruing to the municipal general funds during said fiscal year, exclusive of all balances carried forward from preceding years, and any and all appropriations, loans, or gifts made from national, provincial, or private funds.\n\"With the approval of the Secretary of Finance a municipality may, for justifiable cause, exceed the foregoing percentages under such limitations as may be prescribed by the said Secretary.\""}},{"id":"PH-H2100-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Upon the first classification of municipalities provided in this Act, the provisions of existing laws, orders, rules and/or regulations referring to the first class-A municipalities shall apply to the first class or the second class municipalities, as the case may be, and those referring to the first class-B, first class, second class, third class, and the fourth and fifth class municipalities shall apply to the third class, fourth class, fifth class, sixth class, and the seventh class municipalities, respectively, as defined in this Act: Provided, That the term \"first class municipalities,\" or \"municipalities of the first class,\" or \"municipalities belonging to the first class group,\" or other similar term, whenever used in any provision of existing law, order, rule or regulation not expressly amended or modified by this Act, shall, upon the initial classification of municipalities herein provided, apply to the fourth, third, second and first class municipalities as defined in section one hereof: Provided, further, That municipalities with an average total annual revenue of less than five thousand pesos shall not be subject to the financial contribution provided in section two of Republic Act Numbered Nineteen hundred and thirty-nine."}},{"id":"PH-H2100-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The municipal officers mentioned in this Act shall be entitled to receive the full amount of the appropriations for their salaries which may be provided and approved in the corresponding provincial and municipal budgets in accordance with the provisions of section one hereof, any provision of existing laws, rules and regulations to the contrary notwithstanding: Provided, That the maximum rate of compensation authorized for the civil service eligibility, where this is required, of the officer concerned is not exceeded."}},{"id":"PH-H2100-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Paragraphs two, three, four, five, six, seven, eight, nine, and ten of section twenty-two hundred and seventy-three of the Revised Administrative Code, as amended, section three of Republic Act Numbered Thirteen hundred and forty-six, and all other Acts or parts thereof which are inconsistent with any provision of this Act are hereby repealed and/or modified accordingly."}},{"id":"PH-H2100-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of the Revised Administrative Code, as Amended, so as to Provide for the Classification of Municipalities, to Fix the Maximum Limit of the Salaries of Municipal Officers, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2101"] = {"id":"PH-H2101","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2369_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"对《关税海关法典》的修改","en":"An Act to Amend Certain Sections of Republic Act Numbered Nineteen Hundred and Thirty-Seven, Otherwise Known as the Tariff and Customs Code of the Philippines","orig":"An Act to Amend Certain Sections of Republic Act Numbered Nineteen Hundred and Thirty-Seven, Otherwise Known as the Tariff and Customs Code of the Philippines"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2369","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2369_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2101-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-nine hundred and six of Republic Act Numbered Nineteen hundred and thirty-seven, is hereby amended to read as follows:\nSec. 2906 . Vessels in Philippine Coastwise Trade-Ports with cargo sheds. -Every vessel propelled by steam or internal combustion engine and engaged in the Philippine coastwise trade, including barges and lighters towed by such vessels, excepting boats of five tons gross or less or pleasure or non-commercial craft, which berths at a pier, wharf, bulkhead-wharf, river or channel marginal wharf at any national port in the Philippines provided with cargo sheds or which makes fast to any vessel at such wharf, or pier, for the purpose except when in distress, shall pay a berthing fee of two centavos per registered gross ton of the vessel for the first twenty-four hours or part thereof and one centavo per registered gross ton for each succeeding twenty-four hours or part thereof: Provided, That vessels with registered gross tons in excess of one thousand tons shall pay of the first one thousand tons two centavos per registered gross ton and one centavo for each succeeding tonnage for the first twenty-four hours or part thereof; and one-half of the foregoing rates for each succeeding day or part thereof: Provided, further, That the maximum charge shall not exceed one hundred twenty-five pesos for the first day and seventy-five pesos for each succeeding day or part thereof nor shall the minimum charge be less than fifteen pesos for the first day and seven pesos for each succeeding day or part thereof: Provided, still further, That vessels subject to berthing fees as herein prescribed, of less than one hundred gross tons, shall be subject to a minimum charge of not less than four pesos for the first day and two pesos for each succeeding day or part thereof.\""}},{"id":"PH-H2101-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section twenty-nine hundred and seven of Republic Act Numbered Nineteen hundred and thirty-seven, is hereby amended to read as follows:\nSec. 2907 . Same— Port without cargo shed. -Every vessel propelled by steam or internal combustion engine and engaged in coastwise trade including barges and lighters towed by such vessels, which berths at a pier, wharf, bulkhead-wharf, river or channel marginal wharf without a cargo shed at any national port, or which makes fast to any vessel lying at such wharf or pier for any purpose, except those specifically exempted in the preceding subsection, shall pay a berthing fee of one centavo per registered gross ton of the vessel for the first twenty-four hours or part thereof, and one-half centavo per registered gross ton of the vessel for each succeeding twenty-four hours or part thereof: provided, That vessels with registered gross tons in excess of one thousand tons shall pay on the first one thousand tons one centavo per registered gross ton and one-half centavo for each succeeding tonnage for the first twenty-four hours or part thereof; and one-half of the foregoing rates for each succeeding day or part thereof: Provided, further, That the maximum charge shall not exceed thirty-seven pesos and fifty centavos for the first day and fifteen pesos for each succeeding day or part thereof, nor shall the minimum charge be less than four pesos for the first day and two pesos for each succeeding day or part thereof: Provided, still further, That vessels subject to berthing fees as herein prescribed, of less than one hundred gross tons, shall be subject to a minimum charge of not less than two pesos for the first day and one peso for each succeeding day or part thereof.\""}},{"id":"PH-H2101-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section thirty-two hundred and two of Republic Act Numbered Nineteen hundred and thirty-seven, is hereby amended to read as follows:\nSec. 3 2 02 . Vessels engaged in foreign trade. -There shall be collected at all ports and places in the Philippines from any vessel engaged in foreign trade coming to the Philippines from a foreign port or going to a foreign port from the Philippines, twenty-five centavos per net as expressed in her certificate of registry, or seventy centavos per thousand kilograms of articles discharged or laden in Philippines ports, at the option of the master or the consignees of the vessel.\n\"The option herein granted shall be exercised before the vessel departs from her first port of call.\""}},{"id":"PH-H2101-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29"};
  FT["PH-H2102"] = {"id":"PH-H2102","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2370_1959.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"授予菲律宾村社自治权的法案","en":"An Act Granting Autonomy to Barrios of the Philippines","orig":"An Act Granting Autonomy to Barrios of the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2370","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2370_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2102-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the \"Barrio Charter Act.\"\nGeneral Provisions"}},{"id":"PH-H2102-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Definition and general powers of barrios. -Barrios are units of municipalities or municipal districts in which they are situated. They are quasi-municipal corporations endowed with such powers as are herein provided for the performance of particular government functions, to be exercised by and through their respective barrio governments in conformity with law.\nIt shall be competent for them in their proper corporate name to sue and sued, to contract and be contracted with and to acquire and hold real and personal property for purposes herein specified, and generally to exercise the powers herein or otherwise conferred upon them by law.\nOrganization of Barrios"}},{"id":"PH-H2102-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The creation of new barrios. -All barrios existing at the time of the passage of this Act shall come under the provisions hereof.\nUpon petition of a majority of the voters in the areas affected, a new barrio may be created or the name of an existing one may be changed by the provincial board of the province, upon recommendation of the council of the municipality or municipalities in which the proposed barrio is situated. The recommendation of the municipal council shall be embodied in a resolution approved by at least two-thirds of the entire membership of the said council: Provided, However, That no new barrio may be created if its population is less than five hundred persons.\nBarrios shall not be created or their boundaries altered nor their names changed except under the provisions of this Act or by Act of Congress.\nBoundary disputes between barrios within the same municipalities shall be heard and decided by the municipal council, subject to appeal within thirty days from receipt of notice of the decision by the barrio council concerned to the corresponding provincial board, whose decision shall be final.\nBoundary disputes between barrios belongings to different municipalities shall be treated as boundary disputes between municipalities under existing provisions of law.\nAll property rights of the barrios whose boundaries are altered shall be vested in the barrio in which the property is situated after the alteration has been made."}},{"id":"PH-H2102-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The barrio assembly. -The barrio assembly shall consist of all persons who are qualified electors, who are duly registered in the list of barrio assembly members kept by the secretary thereof, and have been residents of the barrio for at least six months.\nThe barrio assembly shall meet at least once a year to hear the annual report of the barrio council concerning the activities and finances of the barrio.\nIt shall meet also when members of the barrio council are to be elected and/or at the call of the barrio council or upon written petition of at least one-fifth of the members of the barrio assembly.\nFor the purpose of conducting business and taking any official action in the barrio assembly, it is necessary for a quorum, which shall consist of at least one-third of the members of the barrio assembly, to be present. All actions involving the raising of taxes, payment of compensation and solicitation of voluntary contributions shall be by a two-thirds vote of those present at the meeting there being a quorum. All other actions may be by a majority vote of those present at the meeting there being a quorum.\nNo meeting of the barrio assembly shall take place unless notice is given one week prior to the meeting except in matters involving public safety or security in which case notice within a reasonable time shall be sufficient. The barrio lieutenant shall act as presiding officer at all meetings of the barrio assembly. The barrio council secretary shall be the secretary of the barrio assembly; and, in his absence or inability, the assistant barrio council discharge the duties of secretary of the barrio assembly: Provided, That the barrio lieutenant may designate a temporary barrio assembly secretary before the elections and qualification of a permanent barrio council secretary and assistant secretary."}},{"id":"PH-H2102-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers of the barrio assembly. -The powers of the barrio assembly shall be as follows:\n(a) to elect members of the barrio council; act upon their resignation, if presented, and fill vacancies therein by election;\n(b) to provide for reasonable compensation of barrio council members when authorized by two-thirds vote of the barrio assembly;\n(c) to adopt measures for the raising of funds for the barrio by taxation and by voluntary contributions;\n(d) to adopt measures for the good of the barrio;\n(e) to decide on measures submitted to it in accordance with law; and\n(f) to enter into contracts for and in behalf of the barrio and to authorize the barrio council so to do."}},{"id":"PH-H2102-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The barrio council. -In each barrio there shall be organized a barrio council which shall have as members the following:\n(a) a barrio lieutenant;\n(b) a barrio treasurer;\n(c) four council members;\n(d) vice barrio lieutenants, in such number as there are sitios in the barrios; or where there are no sitios, one vice barrio lieutenant for every two hundred inhabitants of the barrio: Provided, That no person shall be elected vice barrio lieutenant unless he is a resident of the sitio he shall represent."}},{"id":"PH-H2102-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Election of the barrio council. -The barrio lieutenant, the barrio treasurer, the vice barrio lieutenants, and the four council members shall be elected at a meeting of the barrio assembly.\nThe election shall be held on the second Sunday of January of even-numbered years: Provided, That if the meeting is not held on the second Sunday of January, it may be held on any day thereafter within the month of January to be determined by the barrio council. The meeting shall be called by the barrio lieutenant who shall preside over the meeting. The Assembly shall elect a board of three election tellers, one of whom shall be a school teacher who shall act as the chairman, to conduct the election and count the votes.\nAll members of the barrio assembly as defined in section four shall have the right to vote at such elections. Voting shall be by secret ballot: Provided, That open voting may be allowed if two-thirds votes of the qualified voters present in the meeting shall so decide. No votes may be cast by proxy.\nThose who obtain the highest number of votes for the position for which they are candidates shall be declared elected by the election tellers and shall assume office immediately by taking the oath of office before any person authorized to administer oaths. In case of a tie, the same shall be decided by drawing lots and the winner shall be proclaimed.\nAll disputes as to procedure before the balloting shall be decided by the board of election tellers.\nAll disputes over barrio elections shall be brought before the justice of the peace court of the municipality concerned; in the determination and decision thereof, the court shall follow as closely as possible the procedure prescribed for inferior courts in Rule 4, Rules of Court. The decision of the justice of the peace court shall be appealable pursuant to the Rules of Court to the court of first instance whose decision shall be final on questions of fact.\nThe members of the barrio council shall hold office for two years from the time of their election and qualification or until their successors are duly elected and qualified. In no use shall a member of the council be elected to the same position for more than three consecutive terms, but after two years shall have elapsed from the expiration of his last term he shall again be eligible for election to the same position."}},{"id":"PH-H2102-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Qualifications for election to the barrio council. -Candidates for election to the barrio council:\n(a) Must be a qualified elector and must have been a resident of the barrio for at least six months prior to the election; and\n(b) Must no have been convicted of a crime involving moral turpitude or of a crime which carries a penalty of at least one year’s imprisonment."}},{"id":"PH-H2102-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The municipal mayor shall exercise the power of supervision over barrio officials. -He shall receive and investigate complaints made under oath against barrio officers for neglect of duty, oppression, corruption or other form of misconduct in office, and conviction by final judgment of any crime involving moral turpitude. For minor delinquency, he may reprimand the offender; and if a more severe punishment seems to be desirable, he shall submit written charges touching the matter to the municipal council, furnishing a copy of such charges to the respondent either personally or by registered mail. The municipal mayor may in such case suspend the officer pending action by the council, if in his opinion the charge be one affecting the official integrity of the officer in question, but in no case shall the period of suspension exceed thirty days. Where suspension is thus effected the written charges against the officer shall be filed within five days with the municipal council, which shall adopt the procedure specified in sections twenty-one hundred eighty-nine to twenty-one hundred ninety of the Revised Administrative Code.\nThe decision of the council shall be appealable within ten days from notice thereof to the provincial board, whose decision shall be final.\nPowers, Rights and Duties"}},{"id":"PH-H2102-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Rights and duties of members of the barrio council. -The barrio lieutenant, or in his absence or inability, the vice barrio lieutenant designated by the barrio council, shall discharge the following duties:\n(a) To look after the maintenance of public order in the barrio and to assist the municipal councilor in the performance of his duties in such barrio;\n(b) To preside over the meetings of the barrio assembly and the barrio council;\n(c) To organize a fire brigade;\n(d) To organize and lead an emergency group whenever the same may be necessary for the maintenance of peace ad order within the barrio;\n(e) To approve vouchers relating to the disbursement of barrio funds;\n(f) To attend conventions of barrio lieutenants; and\n(g) To enforce all laws and ordinances which are operative within the barrio and to sign and enter into contracts with the approval of the barrio council.\nThe vice barrio lieutenants shall be peace officers and as such shall take charge of the maintenance of public order in their respective sitios.\nThe council members shall attend the meetings of the barrio council and cooperate with the barrio lieutenant and vice barrio lieutenants in the discharge of their duties."}},{"id":"PH-H2102-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Rights and privileges of incumbent barrio lieutenants. -In addition to the rights and privileges now granted by existing laws to barrio lieutenants, they shall, if they have served their constituents properly, as shown by a resolution of the barrio council, other qualifications being equal:\n(a) Have preference in appointments in and to any government office, agency, or instrumentality or in and to any government-owned or controlled corporation; and\n(b) Have preference to purchase public lands and government-owned or managed agricultural farms or subdivisions, to obtain homesteads, concessions and franchise, and other privileges for the exploitation of the natural resources which are permissible and made available by existing laws.\nAn incumbent barrio lieutenant who is permanently incapacitated from work owing to sickness, disease or injury incurred in line of duty shall receive the necessary hospitalization and medical care from government hospitals free of charge.\nIncumbent barrio lieutenants having children attending public elementary and intermediate schools shall be exempted from paying the corresponding tuition fees."}},{"id":"PH-H2102-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers and duties of the barrio council. -The barrio council shall have the power to promulgate barrio ordinances not inconsistent with law or municipal ordinances.\nAll barrio ordinances shall be submitted within fifteen days after their approval to the municipal council. Barrio ordinances shall take effect thirty days after their approval, unless the municipal council finds that such ordinances are no in accordance with law, in which case, they shall be returned to the barrio council for adjustment, amendment or repeal. In case of disagreement between the barrio council and the municipal council the dispute shall be referred to the provincial fiscal for final action.\nAny violation of barrio ordinances duly promulgated shall be punished by a fine of not more than one hundred pesos or imprisonment of not more than fifteen days, or both such fine and imprisonment, in the discretion of the court.\nThe barrio council shall have the following powers, duties and responsibilities:\n(a) To construct and/or maintain within its boundaries the following public works: barrio roads, bridges, viaducts and sidewalks, playgrounds and parks, school buildings; water supply, drainage, irrigation, sewerage, and public toilet facilities, and other public works and facilities, and for this purpose, to exercise the power of eminent domain with the approval of the municipal council;\n(b) To undertake cooperative enterprises that will improve the economic condition and well-being of the barrio residents. Such enterprises may include stores for the sale or purchase of commodities and/or produce, warehouse, activities relating to agricultural and livestock production and marketing, fishing, and home and barrio industries, and other activities which may promote the welfare of the barrio inhabitants;\n(c) To accept in all or any of the foregoing public works and cooperative enterprises such cooperation as is made available by municipal, provincial and national governmental agencies established by law to render financial, technical and advisory assistance to barrios and to barrio residents: Provided, However, That in accepting such cooperation, the barrio council may not pledge sums of money for expenditure in excess of amounts currently in the barrio treasury or encumbered for other purposes;\n(d) To initiate and submit to the barrio assembly community programs of economic and social benefit to the inhabitants of the barrio;\n(e) To employ or contribute to the expenses of employing community development workers under terms of agreement made with the Office of the Presidential Assistant on Community Development or with any other bureau or agency of the government;\n(f) To submit to the municipal council such suggestions or recommendations as it may see fit for the improvement of its barrio and/or for the welfare of the inhabitants thereof;\n(g) To provide for the publication by town crier or such other means as they see fit, of laws, ordinances and/or matters of public interest;\n(h) To hold benefits in their respective barrios without having to secure permits from the Social Welfare Administration. The proceeds from such benefits shall be tax-exempt and shall go to the barrio general fund, unless previously set aside for a specific purpose;\n(i) To organize at least twice a month such lectures, programs and/or community assemblies as may serve to educate and enlighten the people on moral, civic, political, educational and other matters of public interest.\n(j) To regulate the use of cement, palay or copra driers (patios), or similar project constructed with government funds for public service within the jurisdiction of the barrio and to charge reasonable fees for such use;\n(k) To exercise any powers necessary to carry out the foregoing provisions;\n(l) To organize annually as soon after the barrio council shall have been elected and qualified, committees composed of men and women of high moral standing and integrity in the barrio to take care of the problem of juvenile delinquency, if the same exists, by providing spiritual help and guidance to the juvenile delinquents and by helping them secure wholesome occupations and entertainment in the barrios or elsewhere; and\n(m) To appropriate barrio funds to implement the decisions of the barrio assembly and for purposes herein specified."}},{"id":"PH-H2102-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Procedure in barrio councils. -The barrio lieutenant shall be the presiding officer of the barrio council. In his absence or inability, the vice barrio lieutenant designated by the barrio council shall act as presiding officer.\nRegular meetings of the barrio council shall be held at least once a month at the call of the barrio lieutenant. Special meetings may also be called by him and by any three members of the barrio council at any time.\nIn order to transact business, the barrio council must constitute a quorum of a majority of its members. All ordinances and resolutions must be approved by a majority vote of those present.\nAt the first meeting of the newly elected barrio council, the barrio lieutenant, with the approval of the majority of the council, shall name the chairman and members of the standing and special committees to study and report from time to time on various problems that come before the barrio council.\nThe barrio council may hold its sessions in the barrio hall or public school building of the barrio during hours when there are no classes, or in any hose or lot in the barrio the provisional or permanent use of which may be granted for said purpose free of charge.\nThe barrio council shall elect from among its members a secretary and an assistant secretary. It shall be the duty of the secretary to keep simple minutes of the meetings of both the barrio assembly and the barrio council during his term of office, to keep a list of all qualified barrio assembly members, and be responsible for the custody of all barrio council and barrio assembly records. The assistant secretary shall perform such duties as may be assigned by the barrio council and upon designation by the barrio council shall act as secretary in case of absence or inability of the latter."}},{"id":"PH-H2102-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Taxing powers of the barrio council and the barrio assembly. -The barrio council with the approval of a two-thirds vote of the barrio assembly as provided in section four hereof, may raise, levy, collect and/or accept monies and other contributions from the following sources:\n(a) Voluntary contributions annually from each male or female resident twenty-one years of age or over;\n(b) License on stores, signs, signboards, and billboards displayed or maintained in any place exposed to public view except those displayed at the place or places where profession or business advertised thereby is in whole or in part conducted;\n(c) A tax on gamecocks owned by residents of the barrio and on the cockfights conducted therein: Provided, That nothing herein shall authorize the barrio council to permit cockfights.\n(d) Monies, materials and voluntary labor for specific public works and cooperative enterprises of the barrio raised from resident, landholders, producers and merchants of the barrio;\n(e) Monies from grants-in-aid, subsidies, contributions and revenues made available to barrios from municipal, provincial or national funds;\n(f) Monies from private agencies and individuals;\n(g) An additional percentage, not exceeding one-fourth of one per cent of the assessed valuation of the property within the barrio, collected by the municipal treasurer along with the tax on real property levied for municipal purposes by the municipality and deposited in the name of the barrio with the municipal treasurer: Provided, That no tax or license fee imposed by a barrio council shall exceed fifty per centum of a similar tax or fee levied, assessed or imposed by the municipal council."}},{"id":"PH-H2102-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Share in real estate taxes. -Ten per cent of all real estate taxes collected within the barrio shall accrue to the barrio general fund, which sum shall be deducted in equal amounts from the respective shares of the province and municipality: Provided, That the municipal treasurer may designate the barrio lieutenant and/or the barrio treasurer as his deputy to collect the said taxes."}},{"id":"PH-H2102-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Financial Procedure. -All ordinances for raising barrio funds through taxes and voluntary contributions may be initiated in the barrio council, and submitted to the barrio assembly. Such ordinances may also originate in the barrio assembly which may approve the same finally without further action by the barrio council.\nThe barrio treasurer shall collect all taxes existing (except real property), fees and contributions due the barrio treasury for which he shall issue official receipts. The treasurer, who shall be bonded in any amount to be fixed by the barrio council not exceeding ten thousand pesos, shall be the custodian of the barrio funds and property and shall deposit all collections with the municipal treasurer within a period of one week after receipt of such fees and contributions. He shall disburse the same in accordance with resolutions of the council, upon vouchers signed by the payee and approved by the barrio lieutenant, and subject to the availability of funds in the barrio treasury, and to all existing applicable auditing rules and regulations.\nThe barrio council may provide for necessary travel expenses for the barrio lieutenant or any member of the council on official business.\nThe financial records of the barrio council shall be kept in a simplified manner as prescribed by the municipal treasurer who shall annually audit such accounts and make a report of the audit to the barrio council and to the municipal council."}},{"id":"PH-H2102-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Extent of applicability. -The above provisions shall be made applicable to all barrios within the jurisdiction or chartered cities."}},{"id":"PH-H2102-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Repealing clause. -All existing legislations or regulations relating to barrio government in conflict or inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H2102-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Effectivity of the Act. -This Act shall take effect January first, nineteen hundred and sixty.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Autonomy to Barrios of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2103"] = {"id":"PH-H2103","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2371_1959.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Pacific 广播系统公司在菲律宾建设、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting the Pacific Broadcasting System, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","orig":"An Act Granting the Pacific Broadcasting System, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2371","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2371_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2103-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, the Pacific Broadcasting System, Inc., is hereby granted a franchise to construct, maintain and operate, for commercial purposes and in the public interest, radio broadcasting and television stations in the Philippines: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting station or one television station be begun within two years from the date of approval of this Act, and be completed within four years from said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting and television stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the broadcasting and/or telecasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the determent of the public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H2103-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Thirty-nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations, shall be applied, as far as practicable, to the television stations referred to in section one hereof."}},{"id":"PH-H2103-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"As a condition of the granting of this franchise, the grantee shall execute a bond in favor of the Government of the Philippines, in the sum of fifty thousand pesos, in form and with sureties satisfactory to the Secretary of Public Works Communications, conditioned upon the faithful performance of the grantee’s obligations hereunder during the first three years of the life of this franchise. If, after four years from the date of acceptance of this franchise, the grantee shall have fulfilled said obligations, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H2103-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Acceptance of this franchise shall be given in writing within six months after the approval of this Act. When so accepted by the grantee and upon approval of the bond aforesaid by the Secretary of Public Works and Communications the grantee shall be empowered to exercise the privilege granted thereby."}},{"id":"PH-H2103-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee’s radio broadcasting and television stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave lengths to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H2103-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H2103-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H2103-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the National, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H2103-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H2103-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein at cost, less reasonable depreciation."}},{"id":"PH-H2103-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary used and operation thereof by any department of the Government upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H2103-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H2103-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned, shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H2103-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Wherever in this franchise the term \"grantee\" is used, it shall be held and understood to mean Pacific Broadcasting System, Inc., its representatives, successors or assigns, unless the context indicates otherwise."}},{"id":"PH-H2103-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This franchise shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H2103-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Pacific Broadcasting System, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2104"] = {"id":"PH-H2104","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2372_1959.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Bohol Enterprises, Inc. 在保和省 Tagbilaran 市镇建设、运营和维护制冰厂与冷库并在全省售冰及供应冷库的特许经营权法案","en":"An Act Granting Bohol Enterprises, Inc. a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Tagbilaran, Province of Bohol, and to Sell Ice and to Supply Cold Storage Within the Province of Bohol","orig":"An Act Granting Bohol Enterprises, Inc. a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Tagbilaran, Province of Bohol, and to Sell Ice and to Supply Cold Storage Within the Province of Bohol"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2372","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2372_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2104-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is hereby granted to Bohol Enterprises, Inc., herein referred to as the grantee, a franchise to construct, operate and maintain an ice plant and cold storage in the Municipality of Tagbilaran, Province of Bohol, for the purpose of manufacturing and distributing ice and supplying cold storage within the Province of Bohol and to charge and collect a schedule of prices and rates for the ice and cold storage so furnished, which schedule for prices and rates shall at all times be subject to regulation by the Public Service Commission."}},{"id":"PH-H2104-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Said grantee shall manufacture and supply ice up to the limit of the capacity of its plant, said limit to be determined by the Public Service Commission in such certificate of convenience and public necessity as may be issued by it as prescribed by section four of this Act."}},{"id":"PH-H2104-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or alter any of its apparatus and appurtenance at grantee’s expense."}},{"id":"PH-H2104-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not exercise any right or privilege under this franchise nor commence any construction thereunder, unless and until the grantee shall first file with the Public Service Commission within one hundred and twenty days from the date of the approval of this Act:\n(1) Its written acceptance of the terms and provisions of this Act;\n(2) Its written acceptance of the terms and conditions of the certificate of convenience and public necessity required by law for the granting of this franchise and issued by the Public Service Commission of the form and character provided for in Commonwealth Act Numbered One hundred and forty-six, as amended; and\n(3) A document or documents evidencing receipt by the Treasurer of the Philippines of the deposit or deposits required by law for each certificate of convenience and public necessity as an earnest proof of good faith and guaranty that the grantee shall complete the work within the period to be fixed by the Commission.\nIf the grantee shall not commence the manufacture and distribution of ice and the supplying of cold storage in the places referred to in the certificate of convenience and public necessity, obtained and filed as herein provided, within such period as the Public Service Commission shall have fixed, unless prevented by act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee’s control, said Commission may in its discretion declare such certificate to be null and void, and the deposit or deposits made by the grantee forfeited in favor of the National Government."}},{"id":"PH-H2104-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"After grantee’s compliance with the requirement of the next preceding section, the Public Service Commission, by proper order or writ, shall authorize the construction of necessary work for the purposes of this franchise within a reasonable time to be determined by said Commission.\nUpon determination by the Public Service Commission after a hearing, upon reasonable written notice to the grantee, that the grantee has violated any of the provisions of this section as to the commencement and/or completion of work authorized by the certificate of convenience and public necessity, the said Commission shall declare the bond or bonds forfeited as liquidated damages and not as a penalty to the National Government. The said Commission shall order the return of the deposit as aforestated, together with any interest or dividends thereon received by the Treasurer of the Philippines, to the grantee upon the satisfactory completion of any work authorized by its certificate of convenience and public necessity, in accordance with the terms and conditions of said certificate obtained, and the Treasurer of the Philippines shall return said deposit to the grantee together with said interest and/or dividends immediately upon presentation to him of a certified copy of such order of the Public Service Commission."}},{"id":"PH-H2104-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This franchise is granted subject to the provisions of the Constitution and Commonwealth Act Numbered One hundred forty-six, as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires.\nThe Public Service Commission shall prescribe as a condition for the issuance of the certificate of convenience and public necessity to the grantee that the certificate shall be valid only for a definite period of time and that the violation of any of these conditions shall cause the immediate cancellation of the certificate without the necessity of any express action on the part of the Commission."}},{"id":"PH-H2104-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the provincial treasurer or his authorized representatives, and it shall be the duty of the grantee to submit to the said treasurer quarterly reports in duplicate showing the gross receipts for the quarter past, one of which shall be forwarded by the said treasurer to the Auditor General, who shall keep the same on file."}},{"id":"PH-H2104-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, with the approval of the Congress of the Philippines first had, may sell, lease, grant, convey, assign, give in usufruct or transfer this franchise and all property and rights acquired thereunder to any individual, association or corporation competent to operate the business hereby authorized, but transfer of title to the franchise or any right of ownership or interest acquired under such sale, lease, grant, conveyance, assignment, gift in usufruct or transfer shall not be effective even after such approval shall have been obtained until there shall have been filed in the office of the Public Service Commission an agreement in writing by which the individual, association or corporation, in whose favor such sale, lease, grant, conveyance, assignment, gift in usufruct or transfer is made, shall be firmly bound to comply with all the terms and conditions imposed upon the grantee by this franchise and by any and all certificate of convenience and public necessity theretofore issued by the Public Service Commission and to accept the same subject to all existing terms and conditions."}},{"id":"PH-H2104-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Public Service Commission shall have the power, after a reasonable written notice to the grantee and a hearing of the interested parties, to declare the forfeiture of this franchise and all rights inherent in the same for failure on the part of the grantee to comply with any of the terms and conditions thereof, unless such failure shall have been directly and primarily caused by an act of God, force majeure, usurped right, uprising or other cause beyond the grantee’s control. Against such declaration of forfeiture by the Public Service Commission the grantee may apply for the remedies provided in sections thirty-four and thirty-six of Commonwealth Act Numbered One hundred and forty-six, as amended. The remedy provided herein shall not be a bar to any other remedy provided by existing laws for the forfeiture of this franchise."}},{"id":"PH-H2104-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"In the event of any competing individual, association or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association or corporation."}},{"id":"PH-H2104-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Bohol Enterprises, Inc. a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Tagbilaran, Province of Bohol, and to Sell Ice and to Supply Cold Storage Within the Province of Bohol","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2105"] = {"id":"PH-H2105","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2373_1959.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"修订第 2037 号共和国法的标题及第 1 条与第 10 条并废止其第 3 条的法案","en":"An Act Amending the Title and Sections One and Ten, and Repealing Section Three of Republic Act Numbered Two Thousand Thirty-Seven","orig":"An Act Amending the Title and Sections One and Ten, and Repealing Section Three of Republic Act Numbered Two Thousand Thirty-Seven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2373","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2373_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2105-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The title of Republic Act Numbered Two thousand thirty-seven is amended to read as follows:\n\"An Act granting Mr. Ricardo P. Ocampo, residing at number one hundred forty C. Francisco, Makati, Rizal, Philippines, a temporary permit to construct, install, establish and operate public radiotelephone and radiotelegraph coastal stations, with the corresponding relay stations, and public fixed and public based and land mobile stations and radio-paging system for the reception and transmission of radiotelephone and radiotelegraph communications within the Philippines.\""}},{"id":"PH-H2105-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one of the same Act is amended to read as follows:\nSec. 1 . There is hereby granted and conceded to Mr. Ricardo P. Ocampo, residing at 140 C. Francisco, Makati, Rizal, Philippines, his successors or assigns, the temporary right and privilege of constructing, installing, establishing and operating in the Philippines and at such places as the grantee may select, subject to the approval of the Department Secretary under whose jurisdiction the Radio Control Division is functioning, or any competent authority who is or shall be authorized now or in the future to give said approval, public coastal radio stations with the corresponding relay stations, and public fixed and public based and land mobile stations and radio-paging system for the reception and transmission of wireless messages on radiotelephony (voice) and/or radiotelegraphy, or both, within the Philippines and with vessels at sea and aircrafts over the air, irrespective of whether such vessels and aircrafts are within or without the Philippines.\""}},{"id":"PH-H2105-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section ten of the same Act is amended to read as follows:\nSec. 10 . As a condition of the granting of this temporary permit the grantee shall execute a bond in favor of the Government of the Philippines in the sum of twenty-five thousand pesos, in form and with sureties satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee’s obligations hereunder during the first three years of the life of this temporary permit. If, after three years from the date of the acceptance of this temporary permit, the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H2105-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section three of the same Act is repealed."}},{"id":"PH-H2105-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending the Title and Sections One and Ten, and Repealing Section Three of Republic Act Numbered Two Thousand Thirty-Seven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2106"] = {"id":"PH-H2106","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2374_1959.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予 Bulletine 出版公司在菲律宾建设、维护和运营无线电广播电台与电视台的特许权法案","en":"An Act Granting the Bulletine Publishing Company, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","orig":"An Act Granting the Bulletine Publishing Company, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2374","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2374_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2106-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, the Bulletine Publishing Company, Inc., is hereby granted a franchise, which shall continue in force during the time that the Government has not established similar service at the places selected by the grantee, to construct, maintain and operate, for commercial purposes and in the public interest radio broadcasting and television stations in the Philippines: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting station or one television station be begun within two years from the date of approval of this Act, and be completed within four years from said date: Provided, further, That the grantee shall provide adequate public service time to enable the government, through the said radio broadcasting and television stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the broadcasting and/or telecasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H2106-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes\"; Act Numbered Thirty-nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations, shall be applied, as far as practicable, to the television stations referred to in section one."}},{"id":"PH-H2106-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guaranty for the full compliance and fulfillment of the conditions under which this franchise is grantee."}},{"id":"PH-H2106-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H2106-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes of its real estate, buildings and personal property, exclusively of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H2106-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such stations or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2106-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H2106-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not require any previous censorship or any speech, play, act or scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast, may cut off from the air the speech, play, act or scene of other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the them thereof is indecent or immoral."}},{"id":"PH-H2106-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned, shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H2106-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Bulletine Publishing Company, Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2107"] = {"id":"PH-H2107","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2375_1959.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Felipe Ysmael, Jr. and Co., Inc. 在菲律宾建设、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting the Felipe Ysmael, Jr. &amp; Co., Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","orig":"An Act Granting the Felipe Ysmael, Jr. &amp; Co., Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2375","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2375_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2107-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, the Felipe Ysmael, Jr. & Co., Inc., is hereby granted a franchise to construct, maintain and operate, for commercial purposes and in the public interest, radio broadcasting and television stations in the Philippines: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting station or one television station be begun within two years from the date of approval of this Act, and be completed within four years from said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting and television stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the broadcasting and/or telecasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H2107-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes\"; Act Numbered Thirty-nine hundred ninety-seven , known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations, shall be applied, as far as practicable, to the television stations referred to in section one."}},{"id":"PH-H2107-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall have the right to establish relay stations at such places in the Philippines as it may consider necessary and convenient, as well as the right to establish a closed circuit television."}},{"id":"PH-H2107-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"As a condition of the granting of this franchise, the grantee shall execute a bond in favor of the Government of the Philippines, in the sum of fifty thousand pesos, in form and with sureties satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee’s obligations hereunder during the first three years of the life of this franchise. If, after four years from the date of acceptance of this franchise, the grantee shall have fulfilled said obligations, or as soon thereafter as the guarantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H2107-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Acceptance of this franchise shall be given in writing within six months after the approval of this Act. When so accepted by the grantee and upon approval of the bond aforesaid by the Secretary of Public Works and Communications the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H2107-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee’s radio broadcasting and television stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave lengths to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H2107-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H2107-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H2107-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall hold the National, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H2107-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H2107-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such stations or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2107-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H2107-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil, or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or thereon or the theme thereof is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H2107-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise is sold, transferred or assigned, shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H2107-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Whenever in this franchise the term \"grantee\" is used, it shall be held and understood to mean Felipe Ysmael, Jr. & Co., Inc., its representatives, successors or assigns, unless the context indicates otherwise."}},{"id":"PH-H2107-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This franchise shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H2107-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Felipe Ysmael, Jr. &amp; Co., Inc. a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2108"] = {"id":"PH-H2108","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2376_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act to Amend Certain Sections of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended","orig":"An Act to Amend Certain Sections of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2376","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2376_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2108-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph (C) of section one hundred eighty-two of Commonwealth Act Numbered Four hundred sixty-six is hereby amended to read as follows:\n\"(C) Exceptions. The following shall be exempt from the tax imposed in this section:\n\"(1) Persons whose gross monthly sales or receipts do not exceed two hundred pesos.\n\"(2) All Filipinos in public market places selling at retail all forms or kinds of food products, meat, fruits, vegetables, game, poultry, fish and other raw and/or cooked food products: Provided , That the term public market shall include tabu, talipapa and other barrio markets.\n\"(3) Peddlers and sellers at fixed stands and other similar selling places engaged exclusively in the sale at retail of domestic meat, fruits, vegetables, game, poultry, fish, and similar domestic food products, whose total stock in trade in any one day does not reach a retail value of one hundred pesos.\n\"(4) Producers of commodities of all classes working in their own homes, consisting of parents and children living as one family, when the value of each day's production by each person capable of working is not in excess of five pesos.\n\"(5) Owners of animal drawn two-wheeled vehicles.\n\"(6) Owners of bancas.\n\"(7) Persons employed in any branch of the service of the Government of the Philippines whose entire professional services are devoted exclusively thereto or are applied under its direction, or persons devoting their entire professional services took any religious, educational, or charitable institution, or hospital, sanitarium, or to similar establishment, not conducted for private gain, in respect to the tax imposed by paragraph (B) of this section.\""}},{"id":"PH-H2108-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one hundred eighty-eight of the same Act, as amended, is further amended to read as follows:\n\"Sec. 188. Transactions and persons not subject to percentage tax. In computing the tax imposed in sections one hundred eighty-four, one hundred eighty-five, and one hundred eighty-six, transactions in the following commodities shall be excluded:\n\"(a) Articles subject to tax under Title IV of this Code.\n\"(b) Agricultural products and the ordinary salt whether in their original form or not when sold, bartered, or exchanged in this country by the producer or owner of the land where produced, as well as all kinds of fish and its by-products when sold, bartered, or exchanged by the fisherman or fishing operator whether in their original state or not.\n\"(c) Minerals and mineral products when sold, bartered, or exchanged by the lessee, concessionaire, or owner of the mineral land from which removed.\n\"(d) Articles subject to tax under section one hundred eighty-nine of this Code.\n\"(e) Articles shipped or exported abroad by the manufacturer or producer, irrespective of any shipping arrangement that may be agreed upon which may influence or determine the transfer of ownership of the articles so exported.\n\"The following shall be exempt from the percentage taxes imposed in sections one hundred eighty-four, one hundred eighty-five and one hundred eighty-six:\n\"(a) Persons whose gross monthly sales or receipts do not exceed two hundred pesos.\n\"(b) All Filipinos in public market places selling at retail all forms or kinds of food products, meat, fruits vegetables, game, poultry, fish and other raw and/or cooked food products.\n\"(c) Peddlers and sellers at fixed stands and other similar selling places engaged exclusively in the sale at retail of domestic meat, fruits, vegetables, game, poultry, fish, and similar food products, whose total stock in trade in any one day does not reach a retail value of one hundred pesos.\n\"(d) Producers of commodities of all classes working in their own homes, consisting of parents and children living as one family, when the value of each day's production by each person capable of working is not in excess of five pesos.\n\"(e) Persons importing articles under the contract for the exclusive use of the Armed Forces of the Philippines.\""}},{"id":"PH-H2108-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section one hundred ninety-one of the same Act, as amended, is further amended to read as follows:\n\"Sec. 191. Percentage tax on road, building, irrigation, artesian well, waterworks, and other construction work contractors, proprietors or operators of dockyards, and others. Road, building, irrigation, artesian well, waterworks, and other construction work contractors; filling contractors; demolition and salvage work contractors; arrastre contractors; persons engaged in the installation of gas or electric light, heat, or power; persons selling water, light, or power, except those paying a franchise tax; proprietors or operators of dockyards, mine drilling apparatus, smelting plants, engraving plants, plating establishments, plastic lamination, establishments, vulcanizing and recapping establishments; establishments for washing and/or greasing of motor vehicles, battery charging, planing or surfacing and recutting of lumber; sawmills under contract to saw and/or cut logs belonging to others; dry-cleaning or dyeing establishments, steam laundries, laundries using washing machines; photographic studios, telephone or telegraph lines or exchanges, broadcasting or wireless stations; funeral parlors, shops for the construction or repair of bicycles or vehicles of any kind, mechanical devices, instruments, apparatus, or furniture of any kind, shoe repairing by machine or any mechanical contrivance, and tailor shops; beauty parlors, dressmakers, milliners, hatters, keepers of hotels, lodging houses, stevedores, warehousemen; plumbers, smiths; house or sign painters; lithographers, publishers, except those engaged in the publication or printing and publication of any newspaper, magazine, review or bulletin which appears at regular intervals, with fixed prices for subscription and sale, and which is not devoted principally to the publication of advertisements; printers and bookbinders, business agents and other independent contractors, except persons, associations and corporations under contract for embroidery and apparel for export as well as their agents and contractors shall pay a tax equivalent to three per centum of their gross receipts.\n\"Keepers of restaurants, refreshment parlors and other eating places, except those inside public market places, and caterers, shall pay a tax of three per centum of their gross receipts. Keepers of bars and cafes where wines or liquors are served shall pay a tax of seven per centum of their gross receipts: Provided , however , That two sets of sales or commercial invoices or receipts serially numbered in duplicate shall be separately prepared and issued, one for each sale of food or refreshment served and another for each sale of wine or liquor served, the originals of which shall be issued to the purchaser or customer. Where such establishments are maintained within the premises or compound of a race track or jai-alai or are accessible to patrons of such race track or jai-alai by means of a connecting door or passage, the keepers of such establishments shall pay a tax of twenty per centum of their gross receipts. Where the establishment is maintained within the premises of a cabaret or night club, or is accessible to patrons thereof by means of a connecting door or passage, the keeper of the establishment shall pay a tax of ten per centum of the gross receipts.\""}},{"id":"PH-H2108-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval: Provided , however , That all taxes heretofore unpaid or uncollected from persons in public market places selling food products as exempted under this Act are hereby condoned.\nApproved: June 20, 1959"}}],"pack":"ph-p29"};
  FT["PH-H2109"] = {"id":"PH-H2109","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2377_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第444号联邦法（即《八小时劳动法》），将管理人员与外部销售人员排除在其适用范围之外，并为其他目的法案","en":"An Act to Amend Commonwealth Act Numbered Four Hundred and Forty-Four Otherwise Known as the Eight-Hour Labor Law, by Excluding Managerial Employees and Outside Sales Personnel from the Scope Thereof, and for Other Purposes","orig":"An Act to Amend Commonwealth Act Numbered Four Hundred and Forty-Four Otherwise Known as the Eight-Hour Labor Law, by Excluding Managerial Employees and Outside Sales Personnel from the Scope Thereof, and for Other Purposes"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 2377","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2377_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2109-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Commonwealth Act Numbered Four hundred and forty-four is hereby amended to read as follows:\n\"Sec. 2. This Act shall apply to all persons employed in any industry or occupation, whether public or private, with the exception of farm laborers, laborers who prefer to be paid on piece work basis, managerial employees, outside sales personnel, domestic servants, persons in the personal service of another and members of the family of the employer working for him.\n\"The term managerial employee' in this Act shall mean either (a) any person whose primary duty consists of the management of the establishment in which he is employed or of a customarily recognized department or subdivision thereof, or (b) any officer or member of the managerial staff.\n\"The term 'outside sales personnel' in this Act shall mean any person who customarily and regularly performs his duties away from his employer's established place or places of business in making or promoting, or in helping make or promote, the sales of his employer's products, and is paid either a basic compensation plus commission, or on commission only."}},{"id":"PH-H2109-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Commonwealth Act Numbered Four Hundred and Forty-Four Otherwise Known as the Eight-Hour Labor Law, by Excluding Managerial Employees and Outside Sales Personnel from the Scope Thereof, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2110"] = {"id":"PH-H2110","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2378_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《菲律宾关税与海关法典》，将莱特省Maasin设为入境口岸的法案","en":"An Act Making Maasin, Province of Leyte, a Port of Entry by Amending the Tariff and Customs Code of the Philippines","orig":"An Act Making Maasin, Province of Leyte, a Port of Entry by Amending the Tariff and Customs Code of the Philippines"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2378","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2378_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2110-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seven hundred one of Republic Act Numbered Nineteen hundred thirty-seven, otherwise known as the Tariff and Customs Code of the Philippines, is amended to read as follows:\nSec. 701 . Collection Districts and Ports of Entry thereof. -For administrative purposes, the Philippines shall be divided into as many collection districts as there are at present existing, the respective limits of which may be changed from time to time by the Commissioner, upon the approval of the department head. The principal ports of entry for the respective collection districts shall be Manila, Sual, Tabaco, Cebu, Pulupandan, Sia-in, Iloilo, Davao, Legaspi, Zamboanga, Jolo, Aparri, Jose Panganiban, Cagayan, Tacloban, San Fernando, Hinigaran, Dumaguete City, Maasin and Batangas.\""}},{"id":"PH-H2110-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Making Maasin, Province of Leyte, a Port of Entry by Amending the Tariff and Customs Code of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2111"] = {"id":"PH-H2111","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2379_1959.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Segundino B. Inovejas 在萨马省 Catbalogan 市镇建设、运营和维护制冰厂并在该地销售冰的特许权法案","en":"An Act Granting Segundino B. Inovejas a Franchise to Construct, Operate and Maintain an Ice Plant in the Municipality of Catbalogan, Province of Samar, and to Sell Ice Therein","orig":"An Act Granting Segundino B. Inovejas a Franchise to Construct, Operate and Maintain an Ice Plant in the Municipality of Catbalogan, Province of Samar, and to Sell Ice Therein"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2379","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2379_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2111-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is granted to Segundino B. Inovejas, hereinafter referred to as the grantee, a franchise to construct, operate and maintain an ice plant in the Municipality of Catbalogan, Province of Samar, for the purpose of manufacturing and distributing ice therein and to charge and collect a schedule or prices and rates for the ice so furnished, which schedule of prices and rates shall at all times be subject to regulation by the Public Service Commission."}},{"id":"PH-H2111-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply is up to the limit of the capacity of his plant, said limit to be determined by the Public Service Commission."}},{"id":"PH-H2111-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or alter any of his plant's apparatus and appurtenances at grantee's expense."}},{"id":"PH-H2111-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the manufacture and distribution of ice in the Municipality of Catbalogan, Province of Samar, within one year from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall become null and void."}},{"id":"PH-H2111-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty six, as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H2111-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspections of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicates showing the gross receipts for the quarter past."}},{"id":"PH-H2111-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H2111-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Segundino B. Inovejas a Franchise to Construct, Operate and Maintain an Ice Plant in the Municipality of Catbalogan, Province of Samar, and to Sell Ice Therein","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2112"] = {"id":"PH-H2112","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2380_1959.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Benguet Consolidated Mining Company 在菲律宾境内建设、设立、维护和运营私人固定点对点、航空、海岸、陆基与陆上移动无线电台的临时许可的法案","en":"An Act Granting the Benguet Consolidated Mining Company a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Aeronautical, Coastal, Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the Benguet Consolidated Mining Company a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Aeronautical, Coastal, Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 2380","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2380_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2112-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Benguet Consolidated Mining Company a temporary permit to construct, establish, maintain and operate in the Philippines, at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point, aeronautical, coastal, land based and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H2112-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said radio stations or any of them on lands of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H2112-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction of at least one of the said stations be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H2112-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunication in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate said radio stations at such places within the Philippines as the interest of the grantee and of its trade and business may justify."}},{"id":"PH-H2112-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies, and wave lengths to be used thereunder, but the grantee may use the international distress frequency of five hundred kilocycles and the high distress frequency of eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H2112-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees are chargeable, as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H2112-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H2112-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the National, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H2112-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, natural or juridical, nor merge with any other person, without the approval of the Congress of the Philippines first had. Any person, natural or juridical, to which this temporary permit may be sold, transferred or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person to which this temporary permit is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit has been originally granted to such person."}},{"id":"PH-H2112-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorized the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H2112-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H2112-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Benguet Consolidated Mining Company a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Aeronautical, Coastal, Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2113"] = {"id":"PH-H2113","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2381_1959.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Sarangani Cattle Co., Inc. 在菲律宾境内建设、维护和运营私人固定点对点无线电台的临时许可的法案","en":"An Act Granting the Sarangani Cattle Co., Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the Sarangani Cattle Co., Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2381","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2381_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2113-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Sarangani Cattle Co., Inc., its successors or assigns, a temporary permit to construct, maintain and operate in the Philippines, at such places as the said company may select, subject to the approval of the Department Secretary under whose jurisdiction the Radio Control Division is functioning, or any competent authority who is or shall be authorized to give said approval, such private fixed point-to-point and land-based radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to consist of two radio apparatus comprising of a receiving and sending radio apparatus."}},{"id":"PH-H2113-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Republic of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and land-based radio stations or any of them on the public domain upon such terms as he may prescribe."}},{"id":"PH-H2113-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the grantee shall start operation of said stations within one and one-half years from the date of approval of this Act."}},{"id":"PH-H2113-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, establish and operate private fixed point-to-point and land-based radio stations in places within the Philippines as the interest of the company and its trade and business may justify."}},{"id":"PH-H2113-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A special right is hereby reserved to the President of the Republic of the Philippines in time of war, insurrection, public peril, calamity or disturbance of peace or order, to cause the closing of the station or stations, or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H2113-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only.\nSection 6-A . The grantee shall file a bond in the amount of fifty thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after four years from the date of the approval of this Act the grantee shall have fulfilled said conditions or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H2113-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H2113-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H2113-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the Corporation Laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H2113-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"the grantee, its successors or assigns, is authorized to operate its private fixed point-to-point radio stations in the medium frequency, high frequency and very high frequency that may be assigned to it by the licensing authority.\nSection 10-A. The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H2113-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H2113-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Sarangani Cattle Co., Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2114"] = {"id":"PH-H2114","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2382_1959.html","fetchedAt":"2026-10-06","articleCount":32,"structureMode":"ARTICLE","title":{"zh":"1959 年医疗法","en":"The Medical Act of 1959","orig":"The Medical Act of 1959"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2382","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 32 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2382_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2114-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Objectives. This Act provides for and shall govern (a) the standardization and regulation of medical education; (b) the examination for registration of physicians; and (c) the supervision, control and regulation of the practice of medicine in the Philippines."}},{"id":"PH-H2114-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Enforcement. For the purpose of implementing the provisions of this Act, there are created the following agencies: the Board of Medical Education under the Department of Education, and the Board of Medical Examiners under the Commissioner of Civil Service.\nThe Board of Medical Education Its Functions"}},{"id":"PH-H2114-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Composition of Board of Medical Education. The Board of Medical Education shall be composed of the Secretary of Education or his duly authorized representative, as chairman, and the Secretary of Health or his duly authorized representative, the Director of the Bureau of Private Schools or his duly authorized representative, the chairman of the Board of Medical Examiners or his duly authorized representative, a representative of private practitioners, upon recommendation of an acknowledged medical association and a representative chosen by the Philippine Association of Colleges and Universities, as members.\nThe officials acting as chairman and members of the Board of Medical Education shall hold office during their incumbency in their respective positions."}},{"id":"PH-H2114-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Compensation and traveling expenses. The chairman and members of the Board of Medical Education shall not be entitled to any compensation except for traveling expenses in connection with their official duties as herein provided.\nFor administrative purposes, the Board shall hold office in the office of its chairman, who may designate a ranking official in the Department of Education to serve as secretary of the Board."}},{"id":"PH-H2114-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Functions. The functions of the Board of Medical Education shall be:\n(a) To determine and prescribe minimum requirements for admission into a recognized college of medicine;\n(b) To determine and prescribe requirements for minimum physical facilities of colleges of medicine, to wit: buildings, including hospitals, equipment and supplies, apparatus, instruments, appliances, laboratories, bed capacity for instruction purposes, operating and delivery rooms, facilities for out-patient services, and others, used for didactic and practical instructions in accordance with modern trends;\n(c) To determine and prescribe the minimum number and the minimum qualifications of teaching personnel, including student-teacher ratio and curriculum;\n(d) To determine and prescribe the number of students who should be allowed to take up the preparatory course taking into account the capacity of the different recognized colleges of medicine.\n(e) To select, determine and approve hospitals or some departments of the hospitals for training which comply with the minimum specific physical facilities as provided in subparagraph (b) hereof: and\n(f) To promulgate and prescribe and enforce necessary rules and regulations for the proper implementation of the foregoing functions."}},{"id":"PH-H2114-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Minimum required courses. Students seeking admission to the medical course must have a bachelor of science or bachelor of arts degree or their equivalent and must have taken in four years the following subjects with their corresponding number of units:\nUnit\nEnglish 12 Latin 3 Mathematics, including Accounting and Statistics 9 Philosophy, including Psychology and Logic 12 Zoology and Botany 15 Physics 8 Chemistry 21 Library Science 1 Humanities and Social Sciences 12 Twelve units of Spanish shall be required pursuant to Republic Act Numbered Seven hundred nine; but commencing with the academic year nineteen hundred sixty to nineteen hundred sixty-one, twenty-four units of Spanish shall be required pursuant to Republic Act Numbered Eighteen hundred and eighty-one as cultural, social and nationalistic studies.\nProvided, That the following students may be permitted to complete the aforesaid preparatory medical course in shorter periods as follows:\n(a) Students whose general average is below eighty-five per cent but without any grade of failure or condition may be allowed to pursue and finish the course in three academic years and the intervening summer sessions; and\n(b) Students whose general average is eighty-five per cent or over may be permitted to finish the course in three academic years by allowing them to take each semester the overload permitted to bright students under existing regulations of the Bureau of Private Schools.\nProvided, That upon failure to maintain the general average of eighty-five per cent, students under (b) shall automatically revert to the category of students under (a) and those under (a), upon having any grade of failure or condition, shall automatically revert to the category of students required to pursue the preparatory course in four years mentioned above.\nThe medical course shall be at least five years, including not less than eleven rotating internship in an approved hospital, and shall consist of the following subjects:\nAnatomy\nPhysiology\nBiochemistry and Nutrition\nPharmacology\nMicrobiology\nParasitology\nMedicine and Therapeutics\nGenycology\nOpthalmology, Otology, Rhinology and Laryngology\nPediatrics\nObstetrics\nSurgery\nPreventive Medicine and Public Health\nLegal Medicine, including Medical Jurisprudence and Ethics."}},{"id":"PH-H2114-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Admission requirements. The medical college may admit any student to its first year class who has not been convicted by any court of competent jurisdiction of any offense involving moral turpitude, and who presents (a) a certificate showing completion of a standard high school course, (b) a record showing completion of a standard preparatory medical course as herein provided, (c) a certificate of registration as medical student, (d) a certificate of good moral character issued by two former professors in the pre-medicine course, and (e) birth certificate and marriage certificate, if any. Nothing in this Act shall be construed to inhibit any college of medicine from establishing, in addition to the preceding, other entrance requirements that may be deemed admissible.\nFor the purposes of this Act, the term \"College of Medicine\" shall mean to include faculty of medicine, institute of medicine, school of medicine or other similar institution offering a complete medical course leading to the degree of Doctor of Medicine or its equivalent.\nEvery college of medicine must keep a complete record of enrollment, grades and turnover, and must publish each year a catalogue giving the following information:\n1. Date of publication\n2. Calendar for the academic year\n3. Faculty roll indicating whether on full time part time basis\n4. Requirements of admission\n5. Grading system\n6. Requirements for promotion\n7. Requirements for graduation\n8. Medical hours per academic year by departments\n9. Schedule hours per academic year by departments\n10. Number of students enrolled in each class.\nTHE BOARD OF MEDICAL EXAMINERS; REGISTRATION OF PHYSICIANS"}},{"id":"PH-H2114-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Prerequisite to the practice of medicine. No person shall engage in the practice of medicine in the Philippines unless he is at least twenty-one years of age, has satisfactorily passed the corresponding Board Examination, and is a holder of a valid Certificate of Registration duly issued to him by the Board of Medical Examiners."}},{"id":"PH-H2114-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Candidates for board examination. Candidates for Board examinations shall have the following qualifications:\n(1) He shall be a citizen of the Philippines or a citizen of any foreign country who has submitted competent and conclusive documentary evidence, confirmed by the Department of Foreign Affairs, showing that his country's existing laws permit citizens of the Philippines to practice medicine under the same rules and regulations governing citizens thereof;\n(2) He shall be of good moral character, showing for this purpose certificate of civil status;\n(3) He shall be of sound mind;\n(4) He shall not have been convicted by a court of competent jurisdiction of any offense involving moral turpitude; and\n(5) He shall be a holder of the degree of Doctor of Medicine or its equivalent, conferred by a college of medicine duly recognized by the Department of Education."}},{"id":"PH-H2114-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Acts constituting practice of medicine. A person shall be considered as engaged in the practice of medicine (a) who shall, for compensation, fee, salary or reward in any form, paid to him directly or through another, or even without the same, physical examine any person, and diagnose, treat, operate or prescribe any remedy for any human disease, injury, deformity, physical, mental or physical condition or any ailment, real or imaginary, regardless of the nature of the remedy or treatment administered, prescribed or recommended; or (b) who shall, by means of signs, cards, advertisements, written or printed matter, or through the radio, television or any other means of communication, either offer or undertake by any means or method to diagnose, treat, operate or prescribe any remedy for any human disease, injury, deformity, physical, mental or physical condition; or (c) who shall use the title M.D. after his name."}},{"id":"PH-H2114-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Exemptions. The preceding section shall not be construed to affect (a) any medical student duly enrolled in an approved medical college or school under training, serving without any professional fee in any government or private hospital, provided that he renders such service under the direct supervision and control of a registered physician; (b) any legally registered dentist engaged exclusively in the practice of dentistry; (c) any duly registered masseur or physiotherapist, provided that he applies massage or other physical means upon written order or prescription of a duly registered physician, or provided that such application of massage or physical means shall be limited to physical or muscular development; (d) any duly registered optometrist who mechanically fits or sells lenses, artificial eyes, limbs or other similar appliances or who is engaged in the mechanical examination of eyes for the purpose of constructing or adjusting eye glasses, spectacles and lenses; (e) any person who renders any service gratuitously in cases of emergency, or in places where the services of a duly registered physician, nurse or midwife are not available; (f) any person who administers or recommends any household remedy as per classification of existing Pharmacy Laws; and (g) any psychologist or mental hygienist in the performance of his duties, provided such performance is done in conjunction with a duly registered physician."}},{"id":"PH-H2114-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Limited practice without any certificate of registration. Certificates of registration shall not be required of the following persons:\n(a) Physicians and surgeons from other countries called in consultation only and exclusively in specific and definite cases, or those attached to international bodies or organization assigned to perform certain definite work in the Philippines provided they shall limit their practice to the specific work assigned to them and provided further they shall secure a previous authorization from the Board of Medical Examiners.\n(b) Commissioned medical officers of the United States armed forces stationed in the Philippines while rendering service as such only for the members of the said armed forces and within the limit of their own respective territorial jurisdiction.\n(c) Foreign physicians employed as exchange professors in special branches of medicine or surgery whose service may in the discretion of the Board of Medical Education, be necessary.\n(d) Medical students who have completed the first four years of medical course, graduates of medicine and registered nurses who may be given limited and special authorization by the Secretary of Health to render medical services during epidemics or national emergencies whenever the services of duly registered physicians are not available. Such authorization shall automatically cease when the epidemic or national emergency is declared terminated by the Secretary of Health."}},{"id":"PH-H2114-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Board of Medical Examiners, its composition and duties. The Board of Medical Examiners shall be composed of six members to be appointed by the President of the Philippines from a confidential list of not more than twelve names approved and submitted by the executive council of the Philippine Medical Association, after due consultation with other medical associations, during the months of April and October of each year. The chairman of the Board shall be elected from among themselves by the member at a meeting called for the purpose. The President of the Philippines shall fill any vacancy that may occur during any examination from the list of names submitted by the Philippine Medical Association in accordance with the provisions of this Act.\nNo examiner shall handle the examinations in more than four subjects or groups of subjects as hereinafter provided. The distribution of subject to each member shall be agreed upon at a meeting called by the chairman for the purpose. The examination papers shall be under the custody of the Commissioner of Civil Service or his duly authorized representative, and shall be distributed to each member of the Board who shall correct, grade, and sign, and submit them to the said Commissioner within one hundred twenty days from the date of the termination of the examinations.\nA final meeting of the Board for the deliberation and approval of the grades shall be called by the Commissioner of Civil Service immediately after receipt of the records from the members of the Board of Medical Examiners. The secretary of the Board shall submit to the President of the Philippines for approval the names of the successful candidates as having been duly qualified for licensure in alphabetical order, without stating the ratings obtained by each."}},{"id":"PH-H2114-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications of examiners. No person shall be appointed a member of the Board of Medical Examiners unless he or she (1) is a natural-born citizen of the Philippines, (2) is a duly registered physician in the Philippines, (3) has been in the practice of medicine for at least ten years, (4) is of good moral character and of recognized standing in the medical profession, (5) is not a member of the faculty of any medical school and has no pecuniary interest, directly or indirectly, in any college of medicine or in any institution where any branch of medicine is taught, at the time of his appointment: Provided , That of the six members to be appointed, not more than two shall be graduates of the same institution and not more than three shall be government physicians."}},{"id":"PH-H2114-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Tenure of office and compensation of members. The members of the Board of Medical Examiners shall hold office for one year: Provided , That any member may be reappointed for not more than one year. Each member shall receive as compensation ten pesos for each candidate examined for registration as physician, and five pesos for each candidate examined in the preliminary or final physician examination.\nThe President of the Philippines, upon the recommendation of the Commissioner of Civil Service , after due investigation, may remove any member of the Board of Medical Examiners for neglect of duty, incompetency, or unprofessional or dishonorable conduct."}},{"id":"PH-H2114-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Executive Officer and Secretary of the Board. The Secretary of the Boards of Examiners appointed in accordance with section ten of Act Numbered Four thousand seven, as amended, shall also be the secretary of the Board of Medical Examiners, who shall keep all the records, including examination papers, and the minutes of the deliberations of the Board. He shall also keep a register of all persons to whom certificates of registration has been granted; set forth the name, sec, age, and place of birth of each, place of business, post office address, the name of the medical college or university from which he graduated or in which he had studied, together with time spent in the study of the profession elsewhere, the name of the country where the institution is located which had granted to him the degree or certificate of attendance upon clinic and all lectures in medicine and surgery, and all other degrees granted to him from institutions of learning. He shall keep an up-to-date registration book of all duly registered physicians in the Philippines. He shall furnish copies of all examination questions and ratings in each subject of the respective candidates in the physicians examination, one month after the release of the list of successful examinees, to the deans of the different colleges of medicine exclusively for the information and guidance of the faculties thereof. This report shall be considered as restricted information. Any school which violates this rule shall be deprived of such privilege. The secretary of the Board shall likewise keep a record of all registered medical students. He shall keep all the records and proceedings, and issue and receive all papers in connection with any and all complaints presented to the Board."}},{"id":"PH-H2114-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Rules and regulations. The Board of Medical Examiners, with the approval of the Commissioner of Civil Service, shall promulgate such rules and regulations as may be necessary for the proper conduct of the examinations, correction of examination papers, and registration of physicians. The Commissioner shall supervise each Board examination and enforce the said rules and regulations. These rules and regulations shall take effect fifteen days after the date of their publication in the Official Gazette and shall not be changed within sixty days immediately before any examination. Such rules and regulations shall be printed and distributed for the information and guidance of all concerned."}},{"id":"PH-H2114-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Dates of examinations. The Board of Medical Examiners shall give examinations for the registration of physicians, one in May and one in November every year, in the City of Manila or any of its suburbs after giving not less than ten days' notice to each candidate who had filed his name and address with the secretary of the Board."}},{"id":"PH-H2114-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Fees. The secretary of the Board, under the supervision of the Commissioner of Civil Service, shall collect from each candidate the following fees:\nFor registration as medical student P 5.00 For complete physician examination\n75.00 For preliminary or final examination\n40.00 For registration as physician\n20.00 All fees paid as provided herein shall accrue to the funds of the Board of Medical Examiners and be expended for the payment of the compensation of the members thereof. No fees other than those provided herein shall be paid to the Board."}},{"id":"PH-H2114-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Issuance of Certificate of Registration, grounds for refusal of same. The Commissioner of Civil Service and the secretary of the Board of Medical Examiners shall sign jointly and issue certificates of registration to those who have satisfactorily complied with the requirements of the Board. They shall not issue a certificate of registration to any candidate who has been convicted by a court of competent jurisdiction of any criminal offense involving moral turpitude, or has been found guilty of immoral or dishonorable conduct after he due investigation by the Board of Medical Examiners, or has been declared to be of unsound mind."}},{"id":"PH-H2114-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Scope of examination. The examination for the registration of physicians shall consist of the following subjects: (1) Anatomy and Histology, (2) Physiology, (3) Biochemistry, (4) Microbiology and Parasitology, (5) Pharcology and Therapeutics, (6) Pathology, (7) Medicine, (8) Obstetrics and Gynecology, (9) Pediatrics and Nutrition, (10) Surgery and Opthalmology, Otolaryngology and Rhinology, (11) Preventive Medicine and Public Health, and (12) Legal Medicine, Ethics and Medical Jurisprudence: Provided , however , That the examination questions in each subject or group of subject shall at least be ten in number: Provided, further , That the examination questions in Medicine shall include at least three from the following branches: Infectious diseases, Neurology, Dermatology, Allergy, Endocrinology and Cardio-Vascular diseases: Provided , finally , That the examination questions in Surgery shall include at least four questions from the following: Opthalmology, Otology, Rhinology, Laryngology, Orthopedic Surgery and Anesthesiology.\nThe questions shall be the same for all applicants. All answers must be written either in English or Spanish. No name of the examinee shall appear in the examination paper but the examiners shall devise a system whereby each applicant can be identified by number only.\nIn order that a candidate may be deemed to have passed his examination successfully he must have obtained a general average of seventy-five per cent without a grade lower than sixty-five per cent in Medicine, Pediatrics and Nutrition, Obstetrics and Gynecology, and Preventive Medicine and Public Health, and no grade lower than fifty per cent in the rest of the subjects.\nThe preliminary examinations shall comprise of the following subjects:\n(1) Gross Anatomy and Histology\n(2) Physiology\n(3) Biochemistry\n(4) Microbiology and Parasitology"}},{"id":"PH-H2114-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Administrative investigation s. In addition to the functions provided for in the preceding sections, the Board of Medical Examiners shall perform the following duties: (1) to administer oath to physicians who qualified in the examination; (2) to study the conditions affecting the practice of medicine in all parts of the Philippines; (3) to exercise the powers conferred upon it by this article with the view of maintaining the ethical and professional standards of the medical profession; (4) to subpoena or subpoena duces tecum witnesses for all purposes required in the discharge of its duties; and (5) to promulgate, with the approval of the Commissioner of Civil Service, such rules and regulations as it may deem necessary for the performance of its duties in harmony with the provisions of this Act and necessary for the proper practice of medicine in the Philippines.\nAdministrative investigations may be conducted by not less than four members of the Board of Medical Examiners; otherwise the proceedings shall be considered void. The existing rules of evidence shall be observed during all administrative investigations. The Board may disapprove applications for examination or registration, reprimand erring physicians, or suspend or revoke registration certificates, if the respondents are found guilty after due investigations."}},{"id":"PH-H2114-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Procedure and rules. Within five days after the filling of written charges under oath, the respondent physician shall be furnished a copy thereof, without requiring him or her to answer the same, and the Board shall conduct the investigation within five days after the receipt of such copy by the respondent. The investigation shall be completed as soon as practicable."}},{"id":"PH-H2114-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Grounds for reprimand, suspension or revocation of registration certificate. Any of the following shall be sufficient ground for reprimanding a physician, or for suspending or revoking a certificate of registration as physician:\n(1) Conviction by a court of competent jurisdiction of any criminal offense involving moral turpitude;\n(2) Immoral or dishonorable conduct;\n(3) Insanity;\n(4) Fraud in the acquisition of the certificate of registration;\n(5) Gross negligence, ignorance or incompetence in the practice of his or her profession resulting in an injury to or death of the patient;\n(6) Addiction to alcoholic beverages or to any habit forming drug rendering him or her incompetent to practice his or her profession, or to any form of gambling;\n(7) False or extravagant or unethical advertisements wherein other things than his name, profession, limitation of practice, clinic hours, office and home address, are mentioned.\n(8) Performance of or aiding in any criminal abortion;\n(9) Knowingly issuing any false medical certificate;\n(10) Issuing any statement or spreading any news or rumor which is derogatory to the character and reputation of another physician without justifiable motive;\n(11) Aiding or acting as a dummy of an unqualified or unregistered person to practice medicine;\n(12) Violation of any provision of the Code of Ethics as approved by the Philippine Medical Association.\nRefusal of a physician to attend a patient in danger of death is not a sufficient ground for revocation or suspension of his registration certificate if there is a risk to the physician's life."}},{"id":"PH-H2114-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Rights of respondents. The respondent physician shall be entitled to be represented by counsel or be heard by himself or herself, to have a speedy and public hearing, to confront and to cross-examine witnesses against him or her, and to all other rights guaranteed by the Constitution and provided for in the Rules of Court."}},{"id":"PH-H2114-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Appeal from judgment. The decision of the Board of Medical Examiners shall automatically become final thirty days after the date of its promulgation unless the respondent, during the same period, has appealed to the Commissioner of Civil Service and later to the Office of the President of the Philippines. If the final decision is not satisfactory, the respondent may ask for a review of the case, or may file in court a petition for certiorari."}},{"id":"PH-H2114-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Reinstatement. After two years, the Board may order the reinstatement of any physicians whose certificate of registration has been revoked, if the respondent has acted in an exemplary manner in the community wherein he resides and has not committed any illegal, immoral or dishonorable act.\nPENAL AND OTHER PROVISIONS"}},{"id":"PH-H2114-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Penalties. Any person found guilty of \"illegal practice of medicine\" shall be punished by a fine of not less than one thousand pesos nor more than ten thousand pesos with subsidiary imprisonment in case of insolvency, or by imprisonment of not less than one year nor more than five years, or by both such fine and imprisonment, in the discretion of the court."}},{"id":"PH-H2114-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Injunctions. The Board of Medical Examiners may file an action to enjoin any person illegally practicing medicine from the performance of any act constituting practice of medicine if the case so warrants until the necessary certificate therefore is secured. Any such person who, after having been so enjoined, continues in the illegal practice of medicine shall be punished for contempt of court. The said injunction shall not relieve the person practicing medicine without certificate of registration from criminal prosecution and punishment as provided in the preceding section."}},{"id":"PH-H2114-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Appropriation. To carry out the provisions of this Act, there is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of twenty thousand pesos."}},{"id":"PH-H2114-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Repealing clause. All Acts, executive orders, administrative orders, rules and regulations, or parts thereof inconsistent with the provisions of this Act are repealed or modified accordingly."}},{"id":"PH-H2114-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Effectivity. This Act shall take effect upon its approval: Provided , That if it is approved during the time when examinations for physicians are held, it shall take effect immediately after the said examinations: Provided, further , That section six of this Act shall take effect at the beginning of the academic year nineteen hundred sixty to nineteen hundred sixty-one, and the first paragraph of section seven shall take effect four years thereafter.\nApproved: June 20, 1959"}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Medical Act of 1959","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2115"] = {"id":"PH-H2115","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2383_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Porfirio Royo与Clementa Fernandez在达沃省卡帕隆市镇电灯、热力与动力系统特许经营权的法案","en":"An Act Granting Porfirio Royo and Clementa Fernandez a Franchise for an Electric Light, Heat and Power System in the Municipality of Kapalong, Davao","orig":"An Act Granting Porfirio Royo and Clementa Fernandez a Franchise for an Electric Light, Heat and Power System in the Municipality of Kapalong, Davao"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2383","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2383_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2115-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, and to the provisions of the Constitution, there is granted to Porfirio Royo and Clementa Fernandez, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Kapalong, Province of Davao."}},{"id":"PH-H2115-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantees shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2115-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantees shall surrender their franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2115-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 20, 1959."}}],"pack":"ph-p29","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Porfirio Royo and Clementa Fernandez a Franchise for an Electric Light, Heat and Power System in the Municipality of Kapalong, Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
